window.MATH_LESSONS = {"version":"2.36","count":339,"byId":{"CQZSB-20261013-001-001":{"id":"CQZSB-20261013-001-001","method":"逐项检验对象是否确定。","steps":["A中的重复5可去重，得到{5,1,−2,0,7}","实数平方非负，所以x²=−2没有实根，D表示空集","B没有给出接近零的精确标准，C的聪明也无明确判据"],"conclusion":"D可表示空集；A按通常集合记号也可表示集合，单选不唯一。","pitfall":"集合不计重复元素，重复书写不等于不能构成集合。","caveat":"来源仅选D；若想排除A，需要题目额外规定列举书写规范，不能据此否认集合。"},"CQZSB-20261013-001-002":{"id":"CQZSB-20261013-001-002","method":"分别找全部覆盖与共同覆盖的区间。","steps":["A=[−1,3)，B=(0,10)","合并覆盖从−1到10，−1属于A而10不属于任一集合","共同部分满足x>0且x<3"],"conclusion":"A∪B=[−1,10)，A∩B=(0,3)，选C。","pitfall":"并集看至少属于一个，交集看同时属于两个。","caveat":""},"CQZSB-20261013-001-003":{"id":"CQZSB-20261013-001-003","method":"列出两处对数及分母的限制后取交集。","steps":["ln√u有意义要求u>0，另有x≠0","(x−1)(x−2)>0，得x<1或x>2","−(x+4)(x−1)>0，得−4<x<1","两式交集为(−4,1)，再删去0"],"conclusion":"定义域为(−4,0)∪(0,1)，选B。","pitfall":"对数内的平方根不能为0，端点−4、1都不能取。","caveat":""},"CQZSB-20261013-001-004":{"id":"CQZSB-20261013-001-004","method":"同时比较定义域与函数值。","steps":["A中ln x要求x>0，故A只在正半轴等于x","B的√(x²)=|x|，C的四次方根同样等于|x|，二者定义域均为ℝ","D写作±x时同一非零x对应两个值，并非通常单值函数"],"conclusion":"A确实与|x|不同；D按字面也有问题，无法严格保证单选唯一。","pitfall":"函数相等必须定义域相同，不能只做形式化简。","caveat":"来源选A；只有把D补成按x正负取号的分段式，D才可表示|x|，原文未说明。"},"CQZSB-20261013-001-005":{"id":"CQZSB-20261013-001-005","method":"配方并讨论二次项系数。","steps":["根号内=m(x−3)²+8−8m","m<0时|x|足够大便为负，不符合全实数定义","m=0时恒为8，可取","m>0时最小值为8−8m，要求m≤1"],"conclusion":"m∈[0,1]，选C。","pitfall":"不能只用二次式判别式而漏掉m=0的常数情形。","caveat":""},"CQZSB-20261013-001-006":{"id":"CQZSB-20261013-001-006","method":"比较定义域，再化简对应规则。","steps":["A中√(x⁴)=|x²|=x²，两者都定义于ℝ","B的g只定义于[0,+∞)，f定义于ℝ","C左式要求x≥1，右式还允许x<−1，定义域不同","D左式排除x=1，右式没有这一限制"],"conclusion":"按现有选项，只有A是相同函数。","pitfall":"约分与开方化简不能自动补回原来排除的点。","caveat":"D曾有公式转写问题；此处严格按目前可读分式计算，未自行改写原题。"},"CQZSB-20261013-001-007":{"id":"CQZSB-20261013-001-007","method":"检查反三角函数的输入范围。","steps":["arcsin的输入必须在[−1,1]，故−1≤x/3≤1","乘3得到−3≤x≤3","arctan(x/2)对一切实数均有定义，不增加限制"],"conclusion":"定义域[−3,3]，选B。","pitfall":"arctan的自变量没有[−1,1]限制，不要与arcsin混淆。","caveat":""},"CQZSB-20261013-001-008":{"id":"CQZSB-20261013-001-008","method":"先确定指数的范围，再逐层求值域。","steps":["根式要求2^x≤16，即x≤4","当x≤4时，2^x遍历(0,16]","16−2^x遍历[0,16)，开方后遍历[0,4)"],"conclusion":"值域[0,4)，选B。","pitfall":"2^x始终大于0，所以函数值只能趋近4而不能等于4。","caveat":""},"CQZSB-20261013-001-009":{"id":"CQZSB-20261013-001-009","method":"先求f的输入范围，再限制x+1。","steps":["两根式要求1−t≥0且1+t≥0，得−1≤t≤1","代入t=x+1，有−1≤x+1≤1","各边减1，得−2≤x≤0"],"conclusion":"f(x+1)的定义域为[−2,0]，选B。","pitfall":"复合后约束的是内部表达式x+1，而不是直接照抄f的区间。","caveat":""},"CQZSB-20261013-001-010":{"id":"CQZSB-20261013-001-010","method":"用已知复合函数的自变量范围求内部输入范围。","steps":["题设表示x可取[1,2]","令t=x+1，则t依次从2变化到3","因此f所接受的自变量t遍历[2,3]"],"conclusion":"f(x)定义域为[2,3]，选C。","pitfall":"这是由复合函数反求原函数定义域，区间应加1。","caveat":""},"CQZSB-20261013-001-011":{"id":"CQZSB-20261013-001-011","method":"对数真数为正，分母不为零。","steps":["ln(2+x)要求2+x>0，即x>−2","1/x要求x≠0","两条件同时满足为(−2,0)∪(0,+∞)"],"conclusion":"x>−2且x≠0，选D。","pitfall":"x=2没有问题；需要排除的是分母为零的x=0。","caveat":""},"CQZSB-20261013-001-012":{"id":"CQZSB-20261013-001-012","method":"让内层x+3落在原单增区间。","steps":["解−2<x+3<3，得−5<x<0","若x₁<x₂，则x₁+3<x₂+3","由f单增得f(x₁+3)<f(x₂+3)"],"conclusion":"对应单增区间为(−5,0)，选C。","pitfall":"自变量加3使图像向左平移3，区间端点都应减3。","caveat":""},"CQZSB-20261013-001-013":{"id":"CQZSB-20261013-001-013","method":"分别约束两个输入，再求交集。","steps":["1≤x+1/4≤2，得3/4≤x≤7/4","1≤x−1/4≤2，得5/4≤x≤9/4","两区间共同部分为[5/4,7/4]"],"conclusion":"g定义域为[5/4,7/4]。","pitfall":"和式中的每一项都须有定义，因此取交集。","caveat":""},"CQZSB-20261013-001-014":{"id":"CQZSB-20261013-001-014","method":"因式分解并用符号区间求解。","steps":["根号内要求x²−3x+2≥0","分解为(x−1)(x−2)≥0","两因子同号或有一个为0，故x≤1或x≥2"],"conclusion":"定义域为(−∞,1]∪[2,+∞)。","pitfall":"根式允许被开方数为0，所以1和2都要保留。","caveat":""},"CQZSB-20261013-001-015":{"id":"CQZSB-20261013-001-015","method":"分母中的根式和对数都不能为零。","steps":["1/√(9−x²)要求9−x²>0，得−3<x<3","1/ln x要求x>0且ln x≠0，即x≠1","取交集并删去1"],"conclusion":"定义域为(0,1)∪(1,3)。","pitfall":"分母根式要求严格大于0，而非通常根式的非负。","caveat":""},"CQZSB-20261013-001-016":{"id":"CQZSB-20261013-001-016","method":"配方检查根号内的最小值。","steps":["3x²+6x+7=3(x+1)²+4","因(x+1)²≥0，故被开方数≥4>0","任意实数x均满足根式条件"],"conclusion":"定义域为ℝ。","pitfall":"不要看到二次根式就机械寻找两个实根；本题无实零点。","caveat":""},"CQZSB-20261013-001-017":{"id":"CQZSB-20261013-001-017","method":"应用arcsin输入范围并解双边不等式。","steps":["−1≤(2x−1)/3≤1","乘3再加1，得−2≤2x≤4","除2得到−1≤x≤2"],"conclusion":"定义域为[−1,2]。","pitfall":"arcsin允许输入±1，因此两端均为闭端点。","caveat":""},"CQZSB-20261013-001-018":{"id":"CQZSB-20261013-001-018","method":"奇次根不限制实数，检查分母对数。","steps":["∛(2x+3)对任意实数有意义","ln(2x−1)要求2x−1>0，得x>1/2","分母不能为0，故2x−1≠1，即x≠1"],"conclusion":"定义域为(1/2,1)∪(1,+∞)。","pitfall":"奇次根允许负数；不要误加2x+3≥0。","caveat":""},"CQZSB-20261013-001-019":{"id":"CQZSB-20261013-001-019","method":"只检查对数真数。","steps":["ln(x+2)要求x+2>0","解得x>−2","式外减1只改变函数值，不改变输入限制"],"conclusion":"定义域为(−2,+∞)。","pitfall":"减1不在对数真数内，不能写成ln(x+1)。","caveat":""},"CQZSB-20261013-001-020":{"id":"CQZSB-20261013-001-020","method":"先限制有限区间，再找正弦非负部分。","steps":["ln(16−x²)要求−4<x<4","√(sin x)要求sin x≥0","在(−4,4)内，正弦非负的部分为(−4,−π]及[0,π]"],"conclusion":"定义域为(−4,−π]∪[0,π]。","pitfall":"负半轴在(−4,−π]也满足条件，不能只保留[0,π]。","caveat":""},"CQZSB-20261013-001-021":{"id":"CQZSB-20261013-001-021","method":"对两个平移输入分别列不等式。","steps":["1/3<x−2/3<8/3，得1<x<10/3","1/3<x+1/3<8/3，得0<x<7/3","取交集为1<x<7/3"],"conclusion":"定义域为(1,7/3)。","pitfall":"两项要同时有定义，端点沿用严格不等号。","caveat":""},"CQZSB-20261013-001-022":{"id":"CQZSB-20261013-001-022","method":"联立根式、对数及分母条件。","steps":["4−x²≥0，得−2≤x≤2","lg(x−1)要求x>1","分母不能为0，故x−1≠1，即x≠2"],"conclusion":"定义域为(1,2)。","pitfall":"x=2虽然允许根式为0，却使分母lg1=0，仍须排除。","caveat":""},"CQZSB-20261013-001-023":{"id":"CQZSB-20261013-001-023","method":"使f的内部输入恰好等于5。","steps":["令2x−1=5，解得x=3","代入右式4×3²−6×3+3","计算36−18+3=21"],"conclusion":"f(5)=21，选C。","pitfall":"代入右式的是x=3，而不是直接把5代进去。","caveat":""},"CQZSB-20261013-001-024":{"id":"CQZSB-20261013-001-024","method":"用倍角公式把右端改写成sin x的多项式。","steps":["cos2x=1−2sin²x","所以f(sin x)=2−2sin²x","令t=sin x，得f(t)=2−2t²，t∈[−1,1]","因此f(cos x)=2−2cos²x=2sin²x"],"conclusion":"f(cos x)=2sin²x，选B。","pitfall":"应先求f的对应规则，不能只把sin x与cos x在原式中随意互换。","caveat":""},"CQZSB-20261013-001-025":{"id":"CQZSB-20261013-001-025","method":"令t=x−2进行换元。","steps":["t=x−2给出x=t+2","f(t)=(t+2)(t+1)","展开得t²+3t+2，再把t改记为x"],"conclusion":"f(x)=x²+3x+2，选A。","pitfall":"变量名称可改，换元关系中的加减号不可颠倒。","caveat":""},"CQZSB-20261013-001-026":{"id":"CQZSB-20261013-001-026","method":"把√x直接替换为所需的新输入变量。","steps":["令t=√x，则t≥0且原x=t²","题设变为f(t−1)=3t²+t","将t改记为x，得到f(x−1)=3x²+x，x≥0"],"conclusion":"f(x−1)=3x²+x（x≥0），选D。","pitfall":"若求的是f(x)，才需要再将t换成x+1。","caveat":""},"CQZSB-20261013-001-027":{"id":"CQZSB-20261013-001-027","method":"先将复合等式化成平方方程。","steps":["f(φ(x))=[φ(x)]²=4^x","因4^x=(2^x)²，得φ(x)=±2^x","逐项核验，B的2^x确实满足等式"],"conclusion":"给定选项中B成立；不加φ(x)>0等条件时，φ并非唯一。","pitfall":"平方等于正数时有正负两根，不能把负根无故删去。","caveat":"来源选B可用于选项判断，但题干若要求唯一解析式，条件不足；符号还可随x变化。"},"CQZSB-20261013-001-028":{"id":"CQZSB-20261013-001-028","method":"将x与1/x互换，联立消元。","steps":["原式f(x)−3f(1/x)=x，要求x≠0","互换得f(1/x)−3f(x)=1/x","第二式乘3后与第一式相加，得−8f(x)=x+3/x"],"conclusion":"f(x)=−(x+3/x)/8，x≠0。","pitfall":"互换变量后右侧也要变成1/x，并保留非零条件。","caveat":""},"CQZSB-20261013-001-029":{"id":"CQZSB-20261013-001-029","method":"使用反正切主值的取值范围。","steps":["tan在(−π/2,π/2)上严格递增且遍历ℝ","arctan是这一限制后的反函数","任意有限x对应的角严格位于两端之间"],"conclusion":"值域为(−π/2,π/2)，选C。","pitfall":"±π/2只可作为极限，不能作为arctan的实际函数值。","caveat":""},"CQZSB-20261013-001-031":{"id":"CQZSB-20261013-001-031","method":"按题面导数符号换元，再积分。","steps":["令t=sin²x，则0≤t<1","tan²x=t/(1−t)，故f′(t)=t+t/(1−t)=t−1+1/(1−t)","积分得f(t)=t²/2−t−ln(1−t)+C"],"conclusion":"在0≤x<1上，f(x)=x²/2−x−ln(1−x)+C。","pitfall":"题面是f′而非f；求原函数应积分并保留任意常数。","caveat":"来源未显示完整答案；这里只能确定上述输入范围内的原函数，未给初值，C无法确定。"},"CQZSB-20261013-001-032":{"id":"CQZSB-20261013-001-032","method":"从内向外代入一次函数。","steps":["f(x)−1=2x+4","再计算f(2x+4)=2(2x+4)+5","展开合并为4x+13"],"conclusion":"f[f(x)−1]=4x+13。","pitfall":"外层f作用于整个2x+4，应将它整体代入。","caveat":""},"CQZSB-20261013-001-033":{"id":"CQZSB-20261013-001-033","method":"先换元得到导函数，再积分并用初值。","steps":["令t=x³+1，x³=t−1，且t遍历ℝ","f′(t)=1+2(t−1)=2t−1","积分得f(t)=t²−t+C","由f(0)=−1得C=−1"],"conclusion":"f(x)=x²−x−1。","pitfall":"已知的是导函数的复合式，不能把f′直接当f。","caveat":""},"CQZSB-20261013-001-034":{"id":"CQZSB-20261013-001-034","method":"取倒数换元并保留原限制。","steps":["令t=1/x，则x=1/t，且t≠0","f(t)=(1/t)/(1−1/t)=1/(t−1)","原式还要求x≠1，即t≠1"],"conclusion":"题设确定f(x)=1/(x−1)，其中x≠0且x≠1。","pitfall":"化简后的分式在0有值，但原等式没有给出f(0)。","caveat":"来源只列解析式；若需完整定义域，不能由题设自行补定x=0的函数值。"},"CQZSB-20261013-001-035":{"id":"CQZSB-20261013-001-035","method":"按照内层值所在区间选择外层分支。","steps":["g(x)=e^x>0，故比较e^x与1即比较x与0","x<0、x=0、x>0时，f(e^x)分别为1、0、−1","将f(x)的三种值代入e^t，分别得到e、1、e⁻¹"],"conclusion":"f∘g为1(x<0)、0(x=0)、−1(x>0)；g∘f为e(|x|<1)、1(|x|=1)、e⁻¹(|x|>1)。","pitfall":"复合顺序不同，分段条件与最终函数值都会改变。","caveat":""},"CQZSB-20261013-001-036":{"id":"CQZSB-20261013-001-036","method":"利用平方恒等式消去原自变量。","steps":["令t=x+1/x，要求x≠0","t²=x²+2+1/x²，故右侧=t²−2","实数x满足|x+1/x|≥2"],"conclusion":"f(t)=t²−2，题设确定的t范围为(−∞,−2]∪[2,+∞)。","pitfall":"由实数换元所得t不能任意取(−2,2)内的数。","caveat":"若来源只写f(x)=x²−2，它省略了换元所确定的范围；区间内的函数值未由条件给出。"},"CQZSB-20261013-001-037":{"id":"CQZSB-20261013-001-037","method":"辨认反解前后的坐标变量有没有互换。","steps":["y=f(x)反解为x=φ(y)，表达的是同一对横坐标x、纵坐标y的对应关系","每个满足y=f(x)的点也满足x=φ(y)，反之亦然","因此在同一xOy坐标系内两条点集完全一致"],"conclusion":"按题面x=φ(y)，图形完全相同，选C。","pitfall":"只有把反函数改写成y=φ(x)再作图，才通常关于y=x对称。","caveat":"来源给D，与现有题面不一致；若题目原意是y=φ(x)，必须先核对原图，不能硬套D。"},"CQZSB-20261013-001-038":{"id":"CQZSB-20261013-001-038","method":"反函数值就是原函数对应的输入。","steps":["g(28)=t等价于f(t)=28","解t³+1=28，得到t³=27","取实数立方根得t=3"],"conclusion":"g(28)=3。","pitfall":"反函数不是倒数，不能计算1/f(28)。","caveat":""},"CQZSB-20261013-001-039":{"id":"CQZSB-20261013-001-039","method":"利用原定义域确定平方根的符号。","steps":["原函数x>1，故y=1+x²>2","反解x²=y−1，由x>1取正根x=√(y−1)","交换变量名称得到y=√(x−1)"],"conclusion":"反函数为y=√(x−1)，定义域(2,+∞)。","pitfall":"反函数定义域是原值域，不能只写根式自然定义域[1,+∞)。","caveat":""},"CQZSB-20261013-001-040":{"id":"CQZSB-20261013-001-040","method":"将输入与输出的角色互换。","steps":["原图过(2,5)说明f(2)=5","反函数将原输出5映回输入2","因此f⁻¹(5)=2"],"conclusion":"反函数图像必过(5,2)。","pitfall":"坐标互换，不是对两个数取倒数。","caveat":""},"CQZSB-20261013-001-041":{"id":"CQZSB-20261013-001-041","method":"先解出原自变量，再交换变量名。","steps":["原定义域为x>−1/2，值域为ℝ","由y=1−ln(2x+1)，得2x+1=e^(1−y)","解得x=(e^(1−y)−1)/2"],"conclusion":"f⁻¹(x)=(e^(1−x)−1)/2，定义域ℝ。","pitfall":"指数中的1−x不可误写成x−1。","caveat":""},"CQZSB-20261013-001-042":{"id":"CQZSB-20261013-001-042","method":"反函数在1处的值通过原函数方程求出。","steps":["设原函数的输入为t，要求(2t−3)/(t+1)=1","分母要求t≠−1，两边乘t+1得2t−3=t+1","解得t=4，且分母5不为0"],"conclusion":"反函数在1处的值为4。","pitfall":"题中y⁻¹(1)按反函数值理解，不是把函数值取倒数。","caveat":""},"CQZSB-20261013-001-043":{"id":"CQZSB-20261013-001-043","method":"在给定单调支上使用arcsin反解。","steps":["x∈[−π/4,π/4]时2x∈[−π/2,π/2]","所以sin2x遍历[−1,1]，y遍历[−1/2,1/2]","由2y=sin2x得x=(1/2)arcsin(2y)"],"conclusion":"反函数y=(1/2)arcsin(2x)，x∈[−1/2,1/2]。","pitfall":"必须先检查2x位于正弦单调主值区间。","caveat":""},"CQZSB-20261013-001-044":{"id":"CQZSB-20261013-001-044","method":"用正弦界估计整个分式。","steps":["|sin(x+3)|≤1，且2+x²≥2","于是|f(x)|≤1/(2+x²)≤1/2","f(0)=sin3/2≠0，故既非奇函数，也不能是随无穷趋0的非零周期函数"],"conclusion":"函数有界，选A。","pitfall":"正弦平移后不保证奇偶性；分母含x²也不保证整个分式为偶函数。","caveat":""},"CQZSB-20261013-001-045":{"id":"CQZSB-20261013-001-045","method":"计算各选项导数的符号。","steps":["A导数为−3<0，B导数为2x<0（x<0）","C导数为(1/3)ln(e/2)·(e/2)^(x/3)>0，因为e/2>1","D导数为−6/(2x−1)²<0"],"conclusion":"C在该区间递增，故不是单减函数，选C。","pitfall":"指数函数的增减取决于底数是否大于1。","caveat":""},"CQZSB-20261013-001-046":{"id":"CQZSB-20261013-001-046","method":"由两次奇对称推出周期，再化简输入。","steps":["g为奇函数给出f(2−x)=−f(2+x)","令x=t+2，得f(−t)=−f(t+4)，结合f奇性得f(t+4)=f(t)","2023=−1+4×506，所以f(2023)=f(−1)=1"],"conclusion":"f(2023)=1，选B。","pitfall":"f(x+2)为奇函数不表示f周期为2；推出的是周期4。","caveat":""},"CQZSB-20261013-001-047":{"id":"CQZSB-20261013-001-047","method":"求导判断全实轴单调性。","steps":["f′(x)=(e^x+e^(−x))/2","两指数项始终为正，故f′(x)>0","因此任意x₁<x₂均有f(x₁)<f(x₂)"],"conclusion":"在ℝ上单调递增，选D。","pitfall":"原式中的减号在求导后变成加号。","caveat":""},"CQZSB-20261013-001-048":{"id":"CQZSB-20261013-001-048","method":"把同频正弦余弦合并。","steps":["sin x+√3cos x=2sin(x+π/3)","振幅2与相位π/3不改变周期","内层x的系数为1，所以最小正周期为2π"],"conclusion":"最小正周期为2π，选B。","pitfall":"相位偏移不是周期，不能把π/3或π/6当答案。","caveat":""},"CQZSB-20261013-001-049":{"id":"CQZSB-20261013-001-049","method":"令构造函数在−x处求值。","steps":["设h(x)=f(x)−f(−x)，定义域为ℝ","h(−x)=f(−x)−f(x)","提取负号得h(−x)=−h(x)"],"conclusion":"必为奇函数的是D。","pitfall":"f本身没有已知奇偶性；差式才保证反对称。","caveat":""},"CQZSB-20261013-001-050":{"id":"CQZSB-20261013-001-050","method":"对D化简并检验负自变量。","steps":["D可写成h(x)=x(2^x+1)/[2(2^x−1)]，定义域x≠0","令a=2^x，h(−x)=−x(1/a+1)/[2(1/a−1)]","化简得到x(a+1)/[2(a−1)]=h(x)"],"conclusion":"D为偶函数，选D。","pitfall":"先检查定义域关于0对称；x=0虽然可能有极限，原式仍无定义。","caveat":""},"CQZSB-20261013-001-051":{"id":"CQZSB-20261013-001-051","method":"把极限识别为导数的一半，再利用周期。","steps":["令h=−x，则[f(1)−f(1−x)]/x=[f(1+h)−f(1)]/h","题设极限因此为f′(1)/2=−1，得f′(1)=−2","由f(x+4)=f(x)求导，得f′(5)=f′(1)"],"conclusion":"曲线在x=5处斜率为−2，选B。","pitfall":"分母有2x，极限等于导数的一半，不能直接记为f′(1)。","caveat":""},"CQZSB-20261013-001-053":{"id":"CQZSB-20261013-001-053","method":"分别检查分子分母在−x处的变化。","steps":["sin(−x)=−sin x，分子两指数项互换，总和不变","cos⁴(−x)=cos⁴x，分母不变且≥1","所以f(−x)=f(x)，定义域为ℝ"],"conclusion":"该函数为偶函数。","pitfall":"指数函数本身不是偶函数，但这两个指数的和具有对称性。","caveat":""},"CQZSB-20261013-001-054":{"id":"CQZSB-20261013-001-054","method":"先用定义域对称求a，再用函数值对称求b。","steps":["偶函数非空区间定义域须关于0对称，故6a−1=−a，得a=1/7","此时定义域为[−1/7,1/7]，含非零点","f(x)−f(−x)=2bx必须恒为0，故b=0"],"conclusion":"a−b=1/7。","pitfall":"偶函数不仅要求一次项消失，还要求定义域对称。","caveat":""},"CQZSB-20261013-001-055":{"id":"CQZSB-20261013-001-055","method":"将负自变量代入并同乘指数化简。","steps":["f(−x)=(e^x−1)/(e^x+1)","f(x)分子分母同乘e^x，得(1−e^x)/(1+e^x)","因此f(−x)=−f(x)，且分母始终为正"],"conclusion":"f为奇函数。","pitfall":"负号位于整个分式前，不能只比较指数符号。","caveat":""},"CQZSB-20261013-001-056":{"id":"CQZSB-20261013-001-056","method":"先由奇函数在原点为0确定参数。","steps":["奇函数定义于ℝ，故f(0)=0","代入非负分支得log₂2+a=1+a=0，所以a=−1","f(1)=log₂3+2−1=log₂3+1","由奇性f(−1)=−f(1)"],"conclusion":"f(−1)=−log₂3−1。","pitfall":"应先求a；只对非负分支直接代入−1是不允许的。","caveat":"题干在且f(−1)=处存在语句残缺；按现有可确定信息求其值。"},"CQZSB-20261013-001-057":{"id":"CQZSB-20261013-001-057","method":"用奇函数定义直接代入。","steps":["定义域为ℝ，关于0对称","f(−x)=−x+sin(−x)=−x−sin x","整理得f(−x)=−(x+sin x)=−f(x)"],"conclusion":"f(x)=x+sin x为奇函数。","pitfall":"两个奇函数相加仍奇，不能把和误认为奇乘奇的偶性规则。","caveat":""},"CQZSB-20261013-001-058":{"id":"CQZSB-20261013-001-058","method":"按从外到内的层次拆分。","steps":["最外层为e^u，其输入u=ln v","对数输入v=x+√(1+x²)，而√(1+x²)>|x|，所以v>0","D回代得到原式，A继续把根式记为w也得到相同原式"],"conclusion":"D的拆分正确；按字面A也正确，单选不唯一。","pitfall":"复合层次可以细分，增加一个正确中间变量不会改变表达式。","caveat":"来源选D，但现有A同样完整有效，不能为了单选排除A。"},"CQZSB-20261013-001-059":{"id":"CQZSB-20261013-001-059","method":"从平方、正弦、指数到线性逐层拆分。","steps":["B写成w=2x，v=e^w，u=sin v，f=u²，回代为sin²(e^(2x))","D写成v=2x，u=e^v，f=sin²u，回代也完全相同","C未交代v与x的关系，拆分不完整"],"conclusion":"B与D均是正确复合过程，单选不唯一。","pitfall":"sin²u本身可视作一层函数，也可以拆成正弦与平方两层。","caveat":"来源只选B；D只是层次数较少，现有题干未要求必须拆为基本函数单层。"},"CQZSB-20261013-001-060":{"id":"CQZSB-20261013-001-060","method":"从外到内依次命名每层输入。","steps":["令w=−x，再令v=e^w=e^(−x)","令u=sin v，则外层为y=ln u","对数还要求sin(e^(−x))>0"],"conclusion":"复合过程为w=−x，v=e^w，u=sin v，y=ln u。","pitfall":"拆分不能漏掉指数中的负号；有表达式不等于对所有实数有定义。","caveat":""},"CQZSB-20261013-001-062":{"id":"CQZSB-20261013-001-062","method":"每次计算先用当前输入选择分段。","steps":["内层输入0落在0≤x≤1，故f(0)=2","于是f[f(0)]=f(2)","2落在1<x<3，故f(2)=ln(2−1)=ln1=0"],"conclusion":"f[f(0)]=0。","pitfall":"第二次分段依据的是内层输出2，不再依据原输入0。","caveat":""},"CQZSB-20261013-001-063":{"id":"CQZSB-20261013-001-063","method":"比较x²与x的大小来分段。","steps":["x²−x=x(x−1)，零点为0、1","x<0或x>1时乘积为正，取x²","0<x<1时乘积为负，取x","在0、1两式相等，可分配给任意相邻段"],"conclusion":"y=x²（x<0或x>1），y=x（0≤x≤1）。","pitfall":"max是取较大值；不要与min的分段方向混淆。","caveat":""},"CQZSB-20261013-001-064":{"id":"CQZSB-20261013-001-064","method":"按复合顺序从最内层算起。","steps":["3>0，故f(3)=−1","−1≤0，故f(−1)=1","1>0，故f(1)=−1"],"conclusion":"f{f[f(3)]}=−1。","pitfall":"本题作用三次，每次都要依据新的输入重新选分支。","caveat":""},"CQZSB-20261013-001-065":{"id":"CQZSB-20261013-001-065","method":"联立根式与倒数的定义条件。","steps":["√(4+x)要求x≥−4","arctan允许任意实数输入，但其中1/x要求x≠0","取交集并保留合法端点−4"],"conclusion":"定义域为[−4,0)∪(0,+∞)，选C。","pitfall":"−4使根式为0仍合法；课堂手写D把这一端点误删。","caveat":"来源答案记录的是用户误选D；数学核算应选C。"},"CQZSB-20261013-001-066":{"id":"CQZSB-20261013-001-066","method":"分别解反正弦与对数的输入限制。","steps":["arcsin(1−x)要求−1≤1−x≤1，得到0≤x≤2","对数要求(1+x)/(1−x)>0，解得−1<x<1","交集为[0,1)"],"conclusion":"定义域[0,1)，选B。","pitfall":"对数的系数1/2不影响定义域；x=0可取，x=1不可取。","caveat":""},"CQZSB-20261013-001-067":{"id":"CQZSB-20261013-001-067","method":"分开检查分子根式与分母对数。","steps":["16−x²≥0，得−4≤x≤4","ln(x+3)要求x>−3","分母非零要求x+3≠1，即x≠−2","求交并删去−2"],"conclusion":"定义域为(−3,−2)∪(−2,4]。","pitfall":"分子为0允许取值，故4保留；分母对数为0必须排除。","caveat":""},"CQZSB-20261013-001-068":{"id":"CQZSB-20261013-001-068","method":"约束复合函数的内部输入。","steps":["f的输入须满足1≤1+x²≤3","减1得到0≤x²≤2","前半自动成立，后半给出−√2≤x≤√2"],"conclusion":"定义域为[−√2,√2]。","pitfall":"平方不等式要同时保留正、负两侧。","caveat":""},"CQZSB-20261013-001-069":{"id":"CQZSB-20261013-001-069","method":"由复合函数自变量区间求内层的值域。","steps":["已知外面的自变量x可遍历[0,1]","e^x−1严格递增，端点值分别为0与e−1","因此f的实际输入遍历[0,e−1]"],"conclusion":"f(x)的定义域为[0,e−1]。","pitfall":"此题由复合式反求原函数，应求内层值域而不是再次解不等式。","caveat":"按教材默认只取复合式覆盖的输入范围。严格说e^x−1仅覆盖(−1,+∞)，题设不能排除f在t≤−1处另有定义；[0,e−1]是已确定的部分。"},"CQZSB-20261013-001-070":{"id":"CQZSB-20261013-001-070","method":"对两个f的输入分别限制后求交。","steps":["0≤x+1/4≤1，得−1/4≤x≤3/4","0≤x−1/4≤1，得1/4≤x≤5/4","共同部分为[1/4,3/4]"],"conclusion":"定义域为[1/4,3/4]。","pitfall":"相加的两函数须同时有意义，不能取两个区间的并集。","caveat":""},"CQZSB-20261013-001-071":{"id":"CQZSB-20261013-001-071","method":"化简指数并比较自然定义域。","steps":["A与D都等于e^|x|，负x时与e^x不同","B中的√x要求x≥0，定义域比ℝ小","C中实数立方根满足(∛x)³=x，对一切实数成立"],"conclusion":"C与y=e^x是同一函数。","pitfall":"偶次根会引入绝对值或非负限制，奇次根则允许全部实数。","caveat":""},"CQZSB-20261013-001-072":{"id":"CQZSB-20261013-001-072","method":"把平方根化为绝对值。","steps":["√(x²)=|x|","x≥0时|x|=x，而x<0时|x|=−x≠x","故必须将共同定义域限制到非负半轴"],"conclusion":"两式相等的x范围为[0,+∞)，选C。","pitfall":"自然定义域均为ℝ并不说明它们是同一函数；对应值也必须相同。","caveat":""},"CQZSB-20261013-001-073":{"id":"CQZSB-20261013-001-073","method":"对二元式逐项列定义条件。","steps":["分子根式要求4x−y²≥0","分母对数要求1−x²−y²>0，即x²+y²<1","分母还不能为0，故1−x²−y²≠1，即x²+y²≠0"],"conclusion":"定义域为{(x,y) | 4x≥y²，0<x²+y²<1}。","pitfall":"圆盘中心因对数分母为0而被排除，边界圆也不属于定义域。","caveat":""},"CQZSB-20261013-001-074":{"id":"CQZSB-20261013-001-074","method":"应用反正弦范围并排除分母零点。","steps":["−1≤3−x²−y²≤1","移项整理为2≤x²+y²≤4","分母要求x−y²≠0，即x≠y²"],"conclusion":"定义域为{(x,y) | 2≤x²+y²≤4，x≠y²}。","pitfall":"圆环的两条圆周可取，但落在抛物线x=y²上的点须另行删除。","caveat":""},"CQZSB-20261013-001-075":{"id":"CQZSB-20261013-001-075","method":"将整个g(x)代入f的平方位置。","steps":["f(t)=t²+1，g(x)=ln(x+1)","所以f(g(x))=[ln(x+1)]²+1","内层对数要求x>−1"],"conclusion":"f[g(x)]=ln²(x+1)+1，x>−1，选B。","pitfall":"f∘g与g∘f顺序不同，不能写成ln(x²+2)。","caveat":""},"CQZSB-20261013-001-076":{"id":"CQZSB-20261013-001-076","method":"用新变量替换x+1。","steps":["令t=x+1，则x=t−1","f(t)=(t−1)²+(t−1)","展开得t²−t=t(t−1)"],"conclusion":"f(x)=x(x−1)，选D。","pitfall":"替换右端每一个x，不可只改变其中一项。","caveat":""},"CQZSB-20261013-001-077":{"id":"CQZSB-20261013-001-077","method":"同除x²，将分式写成x+1/x的表达式。","steps":["原式要求x≠0，令t=x+1/x","(x+x³)/(1+x⁴)=(x+1/x)/(x²+1/x²)","又x²+1/x²=t²−2，故f(t)=t/(t²−2)"],"conclusion":"f(t)=t/(t²−2)，题设确定范围为|t|≥2。","pitfall":"分式化简后看似允许更多自变量，但原实数换元只覆盖|t|≥2。","caveat":"区间(−2,2)内的函数值无法由此条件确定，不能擅自扩展。"},"CQZSB-20261013-001-078":{"id":"CQZSB-20261013-001-078","method":"核对余弦的四种基本性质。","steps":["−1≤cos x≤1，所以有界","cos(−x)=cos x，故为偶函数","cos(x+2π)=cos x，故有周期","cos0=1、cosπ=−1、cos2π=1，体现先减后增"],"conclusion":"在ℝ上不具全程单调性，选D。","pitfall":"在某些子区间单调，不等于在整个实轴单调。","caveat":""},"CQZSB-20261013-001-079":{"id":"CQZSB-20261013-001-079","method":"检查各因子的奇偶性。","steps":["定义域排除π/2+kπ，关于0对称","x与tan x均为奇函数，乘积为偶函数","cos x为偶函数，因此e^(cos x)也为偶函数","三个因子的乘积满足f(−x)=f(x)"],"conclusion":"f是偶函数，选B。","pitfall":"判断之前须检查tan x导致的定义域缺点仍关于0对称。","caveat":""},"CQZSB-20261013-001-080":{"id":"CQZSB-20261013-001-080","method":"先求定义域，再检查两个因子的符号变化。","steps":["对数真数(1−x)/(1+x)>0，得−1<x<1","(e^x−1)/(e^x+1)在x变为−x时变号","ln[(1+x)/(1−x)]=−ln[(1−x)/(1+x)]，故第二因子也变号"],"conclusion":"两个奇因子的乘积为偶函数，选B。","pitfall":"不能只因式中有对数或指数便断言非奇非偶。","caveat":""},"CQZSB-20261013-001-081":{"id":"CQZSB-20261013-001-081","method":"由分母下界求函数整体界。","steps":["1+x²≥1，故0<1/(1+x²)≤1","f(0)=1，而|x|→∞时f(x)→0","它在负半轴递增、正半轴递减，因此不是全轴单调函数"],"conclusion":"f有界，选A。","pitfall":"0是下确界但不能实际取到，值域为(0,1]。","caveat":""},"CQZSB-20261013-001-082":{"id":"CQZSB-20261013-001-082","method":"用常用对数反解指数式。","steps":["由y+1=10^(x+1)>0，得原值域y>−1","两边取lg，得lg(y+1)=x+1","解出x=lg(y+1)−1并交换变量名"],"conclusion":"反函数为y=lg(x+1)−1，x>−1。","pitfall":"反函数定义域由原值域决定，不能把x=−1纳入。","caveat":""},"CQZSB-20261013-001-083":{"id":"CQZSB-20261013-001-083","method":"限制正弦单调支并反解。","steps":["原x∈(−π/8,π/8)，故2x∈(−π/4,π/4)","y的范围为(−3√2/2,3√2/2)","由sin2x=y/3得x=(1/2)arcsin(y/3)"],"conclusion":"反函数y=(1/2)arcsin(x/3)，x∈(−3√2/2,3√2/2)。","pitfall":"原区间开端点，反函数定义域两端也都是开端点。","caveat":""},"CQZSB-20261013-001-084":{"id":"CQZSB-20261013-001-084","method":"把反函数值转成原函数方程。","steps":["设f⁻¹(3)=t，则2t/(t−1)=3","化为2t=3t−3，得t=3","核对t>1，且f(3)=6/2=3"],"conclusion":"f⁻¹(3)=3，选D。","pitfall":"不能把求反函数值误算为f(3)的倒数。","caveat":""},"CQZSB-20261013-001-085":{"id":"CQZSB-20261013-001-085","method":"将分段条件取并集。","steps":["第一段允许−2<x<0","第二段补入单点x=0","第三段允许0<x≤4","三部分连起来覆盖−2到4，左端不含而右端包含"],"conclusion":"定义域为(−2,4]。","pitfall":"分段函数定义域取各段的并集，不能取交集。","caveat":""},"CQZSB-20261013-001-086":{"id":"CQZSB-20261013-001-086","method":"先求f的定义域，再限制平方输入。","steps":["外层自变量x∈[0,e−1]时，ln(x+1)遍历[0,1]","因此f的定义域为[0,1]","f(x²)要求0≤x²≤1，故−1≤x≤1"],"conclusion":"f(x²)的定义域为[−1,1]。","pitfall":"两步方向不同：先求内层值域，再解新的输入限制。","caveat":""},"CQZSB-20261013-001-087":{"id":"CQZSB-20261013-001-087","method":"化简分式后代入−x。","steps":["f(x)=x(2^x+1)/[2(2^x−1)]，定义域x≠0","令a=2^x，f(−x)=−x(1+a)/[2(1−a)]","约去负号得f(−x)=x(a+1)/[2(a−1)]=f(x)"],"conclusion":"f是偶函数，定义域ℝ去掉0。","pitfall":"x=0是原式分母零点，即使可作连续延拓也不能直接补入。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-2-02":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-2-02","method":"要求偶次根的被开方数非负。","steps":["√(3x+2)有意义要求3x+2≥0","移项得3x≥−2","除以正数3，得到x≥−2/3"],"conclusion":"定义域为[−2/3,+∞)，选D。","pitfall":"端点使根式等于0，允许取到，不能写成开区间。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-3-03":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-3-03","method":"将两个分支的输入区间合并。","steps":["第一分支允许−2<x≤0","第二分支允许0<x≤2","两者在0处由第一段补齐，合并为−2<x≤2"],"conclusion":"定义域为(−2,2]，选C。","pitfall":"定义域看分段条件，不由多项式本身的自然定义域代替。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-4-04":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-4-04","method":"将2x整体替换原式中的x。","steps":["f(t)=t²−2t","令t=2x，得f(2x)=(2x)²−2(2x)","展开计算为4x²−4x"],"conclusion":"f(2x)=4x²−4x，选A。","pitfall":"平方项与一次项都要替换，(2x)²=4x²。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-5-05":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-5-05","method":"先检查输入是否落在任一分段区间。","steps":["三段区间合并为(−∞,4)","2π约为6.28，大于4","2π不符合任一分支的适用条件，所以不能套入其解析式"],"conclusion":"f(2π)无定义，选D。","pitfall":"分段式每个公式只适用于自己的区间，不能任意外推。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-6-06":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-6-06","method":"代入−x检查整体符号。","steps":["定义域为ℝ","f(−x)=2(−x)³−3sin(−x)=−2x³+3sin x","提取负号得f(−x)=−(2x³−3sin x)"],"conclusion":"f为奇函数，选A。","pitfall":"三次幂与正弦都为奇函数，相减仍为奇函数。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-7-07":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-7-07","method":"先证明π是周期，再检查最小性及措辞。","steps":["|sin(x+π)|=|−sin x|=|sin x|，所以π为周期","零点集合为{kπ}，任一正周期T须使f(T)=f(0)=0，故T为π的正整数倍","π/2不是周期，因为f(0)=0而f(π/2)=1"],"conclusion":"最小正周期为π，对应C；若仅问周期，则A的4π、B的2π也成立。","pitfall":"周期的正整数倍仍是周期；最小正周期与任一周期不能混称。","caveat":"现题写周期而非最小正周期，严格单选不唯一；来源C按最小正周期的常用意图成立。"},"CQZSB-B2-D01-090-BF-MATH-8":{"id":"CQZSB-B2-D01-090-BF-MATH-8","method":"将根式条件和分母条件取交集。","steps":["√(x−2)要求x−2≥0，即x≥2","1/(x−5)要求x≠5","从[2,+∞)中删去5，得到两个区间"],"conclusion":"定义域[2,5)∪(5,+∞)，选A。","pitfall":"2可以取，5必须排除，两处端点来自不同限制。","caveat":""},"CQZSB-B2-D01-091-BF-MATH-9":{"id":"CQZSB-B2-D01-091-BF-MATH-9","method":"分别解反正弦和对数条件。","steps":["−1≤x−3≤1，得2≤x≤4","ln(x−2)要求x>2","取交集得2<x≤4"],"conclusion":"定义域(2,4]，选C。","pitfall":"反正弦允许x=2，但对数不允许，因此最终左端开、右端闭。","caveat":""},"CQZSB-B2-D01-092-BF-MATH-10":{"id":"CQZSB-B2-D01-092-BF-MATH-10","method":"合并各段给出的输入区间。","steps":["三段分别允许[−1,0]、(0,2)、[2,+∞)","0由第一段包含，2由第三段包含","因此从−1起到正无穷之间没有缺点"],"conclusion":"定义域[−1,+∞)，选D。","pitfall":"第三段常数e不影响定义域；仍须遵守它的x≥2条件。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-11-08":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-11-08","method":"使内部x+1落在f的原定义域。","steps":["1≤x+1≤2","三边同时减1得0≤x≤1","两端均允许，因为原区间为闭区间"],"conclusion":"f(x+1)的定义域为[0,1]，选A。","pitfall":"已知原函数求复合式时解输入不等式，平移方向不要反。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-12-09":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-12-09","method":"将已知自变量区间映射为f的输入范围。","steps":["复合式允许外部x∈[1,3]","内部t=x−2严格递增，端点变成−1与1","因此t遍历[−1,1]"],"conclusion":"f(x)的定义域为[−1,1]，选C。","pitfall":"此处反求原函数范围，应直接计算x−2的值域。","caveat":""},"CQZSB-B2-D01-093-BF-MATH-13":{"id":"CQZSB-B2-D01-093-BF-MATH-13","method":"逐组比较定义域与对应值。","steps":["A中g只允许x≥0，f允许全部实数","B的g=|x|，负半轴与f=x不同","C中sin²x+cos²x=1，对全部实数成立","D中x³/x排除0，而x²不排除0"],"conclusion":"只有C为相同函数。","pitfall":"约分后公式相同并不能消除原定义域中的缺点。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-14-10":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-14-10","method":"将t³+1整体代入三次多项式。","steps":["φ(u)=u³+1，所以φ(t³+1)=(t³+1)³+1","用(a+1)³=a³+3a²+3a+1，取a=t³","得到t⁹+3t⁶+3t³+2"],"conclusion":"φ(t³+1)=t⁹+3t⁶+3t³+2，选D。","pitfall":"立方的和不能写成各项立方之和，必须保留交叉项。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-15-11":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-15-11","method":"逐层应用加1的规则。","steps":["先求f(x)+1=(x+1)+1=x+2","外层f再给输入加1","故f(x+2)=x+3"],"conclusion":"f[f(x)+1]=x+3，选D。","pitfall":"括号内的额外+1与外层f所加的1都须计入。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-16-12":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-16-12","method":"令新变量等于1−x并替换所有原x。","steps":["令t=1−x，则x=1−t","分子1+x=2−t，分母2x−1=1−2t","所以f(t)=(2−t)/(1−2t)，且t≠1/2"],"conclusion":"f(x)=(2−x)/(1−2x)，x≠1/2，选D。","pitfall":"换元后分子与分母都要同步变换，负号不可只改一处。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-17-13":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-17-13","method":"将sin²x转换成cos x的多项式。","steps":["sin²x=1−cos²x","因此1−2sin²x=2cos²x−1","令t=cos x，t∈[−1,1]，得到f(t)=2t²−1"],"conclusion":"题设确定f(x)=2x²−1（−1≤x≤1），选B。","pitfall":"已知复合式只确定余弦值域内的f，不能凭空确定区间外的值。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-18-14":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-18-14","method":"检验各项在−x处的符号变化。","steps":["A的x³+x、B的e^x−e^(−x)、C的sin³x都为非零奇函数","D的分式r(x)=(e^x−1)/(e^x+1)满足r(−x)=−r(x)","故D在−x处为(−x)(−r(x))=xr(x)"],"conclusion":"D是偶函数，选D。","pitfall":"两个奇函数相乘为偶函数，和式则仍为奇函数。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-19-15":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-19-15","method":"直接对乘积代入−x。","steps":["令h(x)=f(x)f(−x)，定义域为ℝ","h(−x)=f(−x)f(x)","由乘法交换律得h(−x)=h(x)，故h恒为偶函数"],"conclusion":"必正确的是D。","pitfall":"不能假设f自身有奇偶性；结论来自配对乘积结构。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-20-16":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-20-16","method":"用倍角公式统一核查各性质。","steps":["sin x cos x=(1/2)sin2x，故为奇函数且最小正周期为π","导数为cos2x，在0<x<π/4时为正，所以该区间单增","|f(x)|≤1/2，因此有界"],"conclusion":"错误说法为D的无界函数。","pitfall":"幅度1/2给出明确上下界；函数有振荡并不等于无界。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-21-17":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-21-17","method":"先检验奇偶，再核对有界性和周期性。","steps":["f(−x)=(−x)sin(−x)=xsin x=f(x)","取xₙ=π/2+2nπ，则f(xₙ)=xₙ→+∞，故无界","连续周期函数必有界，所以本函数也非周期函数"],"conclusion":"f是偶函数，选B。","pitfall":"正弦有界并不保证乘上无界因子x后的乘积有界。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-22-18":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-22-18","method":"逐项回代复合链检验内层表达式。","steps":["A回代为sin(2x²+1)，符合题目","B回代为sin(2x²+2)，不符","C回代为sin(2x²+1)，也符合","D回代同样为sin(2x²+2)，不符"],"conclusion":"A与C均正确，按现有选项单选不唯一。","pitfall":"正确复合链可以有不同层数，须以回代结果为准。","caveat":"来源仅选A；C的u=v+1、v=2x²完全合法，不能因多一步而排除。"},"CQZSB-B2-D01-094-BF-MATH-23":{"id":"CQZSB-B2-D01-094-BF-MATH-23","method":"对数真数严格为正并解二次不等式。","steps":["−x²+3x=x(3−x)","要求x(3−x)>0","两零点为0、3，在两根之间两因子均为正，其他区域乘积非正"],"conclusion":"定义域(0,3)，选C。","pitfall":"对数真数不能为0，因此两个零点都排除。","caveat":""},"CQZSB-B2-D01-095-BF-MATH-24":{"id":"CQZSB-B2-D01-095-BF-MATH-24","method":"用分式符号求对数真数为正的区间。","steps":["要求(x+1)/(x−1)>0","临界点为−1、1，两因子同号时分式为正","得x<−1或x>1，且−1真数为0、1分母为0均不可取"],"conclusion":"定义域(−∞,−1)∪(1,+∞)，选C。","pitfall":"负分子与负分母的比值也为正，不能只保留x>1。","caveat":""},"CQZSB-B2-D01-096-BF-MATH-25":{"id":"CQZSB-B2-D01-096-BF-MATH-25","method":"联立根式与指数型对数条件。","steps":["4−x²≥0，得−2≤x≤2","ln(e^x−1)要求e^x>1，即x>0","两者交集为0<x≤2"],"conclusion":"定义域(0,2]，选B。","pitfall":"x=0会使对数真数为0；x=2只令根式为0，仍可取。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-26-19":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-26-19","method":"限制两个内部输入并取交。","steps":["−2≤3x−1≤4，得−1/3≤x≤5/3","−2≤x²≤4，其中下界自动成立，上界给出−2≤x≤2","两区间相交为[−1/3,5/3]"],"conclusion":"g定义域为[−1/3,5/3]，选C。","pitfall":"平方输入限制得正负两侧，但最终还要受线性输入约束。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-27-20":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-27-20","method":"先求f的根式定义域，再代入新输入。","steps":["x−2≥0且5−x≥0，故f的定义域为[2,5]","f(2x−1)要求2≤2x−1≤5","加1并除2得到3/2≤x≤3"],"conclusion":"定义域[3/2,3]，选D。","pitfall":"不能将[2,5]直接作为复合函数的定义域。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-28-21":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-28-21","method":"利用平方恒等式改写换元右端。","steps":["令t=x+1/x，原x≠0且|t|≥2","t²=x²+2+1/x²","所以x²+1/x²+4=t²+2"],"conclusion":"f(t)=t²+2，题设确定|t|≥2，对应C。","pitfall":"恒等式里有额外的2，移项后再加4得到+2而不是+4。","caveat":"题设未约束(−2,2)内的f值；解析式结论限于实数换元覆盖范围。"},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-29-22":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-29-22","method":"对构造式直接代入−x，并核查其他项。","steps":["令h(x)=f(x)+f(−x)，则h(−x)=f(−x)+f(x)=h(x)","A的x²cot x为奇函数，外取sin仍为奇函数","C在−x处变号，D因(√(1+x²)−x)(√(1+x²)+x)=1也在−x处变号"],"conclusion":"必为偶函数的是B。","pitfall":"连续性不是这条结论的必要条件，关键是定义域对称且两项互换。","caveat":""},"CQZSB-B2-D01-088-BF-MATH-1":{"id":"CQZSB-B2-D01-088-BF-MATH-1","method":"把根式与对数条件同时满足。","steps":["√(3−x)要求3−x≥0，即x≤3","lg(x+1)要求x+1>0，即x>−1","取交集得到−1<x≤3"],"conclusion":"定义域为(−1,3]。","pitfall":"−1使对数无定义而3使根式为0，故一开一闭。","caveat":""},"CQZSB-B2-D01-089-BF-MATH-2":{"id":"CQZSB-B2-D01-089-BF-MATH-2","method":"把分母根式和对数的限制取交集。","steps":["分母√(1−x)必须大于0，故x<1。","lg(3x+1)要求3x+1>0，故x>−1/3。","两条件同时满足，端点均排除。"],"conclusion":"定义域为(−1/3,1)。","pitfall":"分母中的根号要求严格大于0，不能取x=1。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-3-23":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-3-23","method":"让内层自变量落在原定义域。","steps":["f的输入范围是−1<t≤2。","令t=x−1，得−1<x−1≤2。","各端加1，得0<x≤3。"],"conclusion":"定义域为(0,3]。","pitfall":"平移的是输入限制，开闭端点也必须保留。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-4-24":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-4-24","method":"从内向外求值，每次重新判断分段。","steps":["−3<−2，所以f(−3)=(−3)²=9。","9>0，外层要用3ˣ这一段。","因此f(f(−3))=f(9)=3⁹=19683。"],"conclusion":"结果为3⁹，即19683。","pitfall":"外层分段由9决定，不能继续使用平方这一段。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-5-25":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-5-25","method":"把g(x)整体放进f的自变量位置。","steps":["f(t)=1+t²。","代入t=g(x)=sin x，得到f(g(x))=1+(sin x)²。"],"conclusion":"f[g(x)]=1+sin²x，x∈ℝ。","pitfall":"函数复合不是函数相乘，也不是sin(1+x²)。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-6-26":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-6-26","method":"令t=1/x换元，并同步转换范围。","steps":["x>1时，t=1/x满足0<t<1。","以x=1/t代入右边，(1/t)/(1−1/t²)=t/(t²−1)。","将t改名为x，保留换元得到的范围。"],"conclusion":"f(x)=x/(x²−1)，0<x<1。","pitfall":"代数式可在更大范围有意义，但题设只确定(0,1)上的函数值。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-7-27":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-7-27","method":"利用给定单调区间反解正弦。","steps":["原区间使3x∈[−π/2,π/2]，正弦在此严格递增。","y=2sin3x的值域为[−2,2]。","由3x=arcsin(y/2)，得x=arcsin(y/2)/3，再交换变量。"],"conclusion":"反函数为y=arcsin(x/2)/3，x∈[−2,2]。","pitfall":"反函数定义域是原值域，不能照抄[−π/6,π/6]。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-8-28":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-8-28","method":"先求受限对数函数的值域再反解。","steps":["2<x<e+1给出1<x−1<e，所以0<y<1。","y=ln(x−1)化为x−1=eʸ，即x=eʸ+1。","交换x、y，保留新自变量范围。"],"conclusion":"反函数为y=eˣ+1，x∈(0,1)。","pitfall":"原函数有限区间的限制不能在求反函数时丢掉。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-9-29":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-9-29","method":"反函数求值转化为原函数方程。","steps":["设f⁻¹(1)=t，则f(t)=1。","2eᵗ−1=1，得eᵗ=1，所以t=0。"],"conclusion":"f⁻¹(1)=0。","pitfall":"f⁻¹不是1/f；这里求的是输出1所对应的输入。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-10-30":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-10-30","method":"先恢复f的输入范围，再处理新复合。","steps":["当−1<x≤3时，1−3x从4的左侧递减到−8，故f的定义域为[−8,4)。","要求−8≤x−3<4。","各端加3得−5≤x<7。"],"conclusion":"f(x−3)的定义域为[−5,7)。","pitfall":"乘负数后不等号反向，原来的左右端开闭也会交换。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-11-31":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-11-31","method":"把复合等式写成对数方程。","steps":["由f(t)=ln(t+5)，得ln(g(x)+5)=x²。","两边取指数，g(x)+5=e^(x²)。","解得g(x)=e^(x²)−5，且g(x)+5始终为正。"],"conclusion":"g(x)=e^(x²)−5，x∈ℝ。","pitfall":"e^(x²)与(eˣ)²不同，指数整体是x²。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-12-32":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-12-32","method":"用x和−x建立二元方程组。","steps":["原式为2f(x)+f(−x)=x+2。","将x换成−x，得2f(−x)+f(x)=−x+2。","原式乘2再减去第二式，得3f(x)=3x+2。"],"conclusion":"f(x)=x+2/3。","pitfall":"变换x时右端也必须变为−x+2；常数2不会变号。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-13-33":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-13-33","method":"偶函数同时要求定义域对称和函数值相等。","steps":["区间[2a−5,a+1]关于0对称，故2a−5=−(a+1)，得a=4/3。","此时区间为[−7/3,7/3]，含非零数；f(−x)=f(x)给出−bx=bx，所以b=0。","a²+b²=16/9。"],"conclusion":"a²+b²=16/9。","pitfall":"只令一次项系数为0还不够，定义域的对称性才能确定a。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-14-34":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-14-34","method":"先用周期降到已知点，再用奇性变号。","steps":["7=1+2×3，由周期3得f(7)=f(1)。","奇函数满足f(1)=−f(−1)=1。"],"conclusion":"f(7)=1。","pitfall":"奇函数的符号变化与周期平移是两步，不能把f(7)直接等于f(−1)。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-15-35":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-15-35","method":"交叉相乘解出原自变量。","steps":["y(x+3)=2x−1，整理得(y−2)x=−1−3y。","因此x=(3y+1)/(2−y)，要求y≠2。","原函数x≠−3且不可能取值2，其余实数均能取到。"],"conclusion":"f⁻¹(x)=(3x+1)/(2−x)，x≠2。","pitfall":"交换变量后分母为2−x，符号不能写反。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-FILL-16-36":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-FILL-16-36","method":"按内层到外层依次代入。","steps":["v=5ˣ>0，所以u=ln(5ˣ)=x ln5。","把u代入y=u²，得y=(x ln5)²。"],"conclusion":"复合函数为y=x²(ln5)²，x∈ℝ。","pitfall":"ln(5ˣ)=x ln5，不能误写成(ln5)ˣ。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-3-45":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-3-45","method":"按最后一步运算向内分层。","steps":["最外层是立方，令y=u³。","中间一层是对数，令u=ln v；最内层令v=1/x。","对数真数1/x>0，因此x>0。"],"conclusion":"可分解为y=u³，u=ln v，v=1/x。","pitfall":"分解后仍须满足x>0，不能仅用x≠0。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-4-46":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-4-46","method":"识别多项式、正割和五次根三层。","steps":["先令v=x²−2x。","再令u=sec v=1/cos v，最后令y=⁵√u。","五次根允许负数，但正割要求cos(x²−2x)≠0。"],"conclusion":"分解为y=⁵√u，u=sec v，v=x²−2x。","pitfall":"奇次根不要求被开方数非负；真正限制来自正割分母。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-5-47":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-5-47","method":"按根式平移、对数、指数分层。","steps":["先令v=√(1+x)−1，再令u=ln v，最后y=2ᵘ。","ln v要求v>0，即√(1+x)>1，从而x>0。"],"conclusion":"可分解为y=2ᵘ，u=ln v，v=√(1+x)−1；x>0。","pitfall":"不能只检查根号中的1+x≥0，还要保证对数真数大于0。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-6-48":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-2-6-48","method":"从最里面的平方加1开始分解。","steps":["令v=x²+1，故v≥1。","令u=1/v，最后令y=arctan u。","v始终不为0，反正切对任意实数有定义。"],"conclusion":"分解为y=arctan u，u=1/v，v=x²+1；定义域ℝ。","pitfall":"arctan(1/v)不是1/arctan v，运算层次不能交换。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-3-49":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-3-49","method":"在实指数有意义的条件下代入−x。","steps":["通常取a>0，此时aˣ、a⁻ˣ在ℝ上都有定义。","f(−x)=(a⁻ˣ+aˣ)/2=f(x)。"],"conclusion":"在通常条件a>0下，f为偶函数。","pitfall":"先确认底数条件；实指数函数不能任取负底数。","caveat":"题干未写底数限制；按实指数函数常规约定a>0讨论，a=1时为常函数1。"},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-4-50":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-4-50","method":"用正弦奇性和余弦偶性判断。","steps":["分母1+cos²x≥1，定义域是关于0对称的ℝ。","sin³(−x)=−sin³x，而1+cos²(−x)=1+cos²x。","故f(−x)=−f(x)。"],"conclusion":"f(x)为奇函数。","pitfall":"sin³x指(sin x)³，三次方仍保留正弦的奇性。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-5-51":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-5-51","method":"比较两条曲线大小，按交点分段。","steps":["sin x−cos x=√2 sin(x−π/4)，在[0,π]内仅于π/4变号。","0≤x≤π/4时cos x≥sin x；π/4<x≤π时sin x>cos x。","图像先沿cos曲线由(0,1)降到(π/4,√2/2)，再沿sin曲线上升到(π/2,1)并降到(π,0)。"],"conclusion":"y=cos x（0≤x≤π/4）；y=sin x（π/4<x≤π）。","pitfall":"max取较大值；在交点两式相等，端点归入任一段皆可。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-6-52":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-6-52","method":"把右边配成内层表达式的平方。","steps":["令t=2ˣ+2⁻ˣ，由正数和不等式t≥2，且所有t≥2都能取到。","t²=4ˣ+2+4⁻ˣ，所以原等式右边=t²−2。","因此f(t)=t²−2，t≥2。"],"conclusion":"f(x)=x²−2，x≥2。","pitfall":"不要遗漏内层值域[2,+∞)；题设不决定x<2时的f值。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-7-53":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-7-53","method":"把1+1/x设为新变量并检查复合限制。","steps":["令t=(x+1)/x=1+1/x，x≠0，故t≠1。","右端(2x+1)/x=2+1/x=t+1，故f(t)=t+1。","f(f(x))=(x+1)+1=x+2，但需x≠1且x+1≠1，即x≠0,1。","2在定义域内，f(2)=3。"],"conclusion":"f(x)=x+1（x≠1）；f(f(x))=x+2（x≠0,1）；f(2)=3。","pitfall":"复合时外层输入也要属于f的定义域，不能漏掉x=0。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-8-54":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-8-54","method":"判断两因子的奇偶性再相乘。","steps":["设g(x)=2ˣ+2⁻ˣ，则g(−x)=2⁻ˣ+2ˣ=g(x)，为偶函数。","f为奇函数，定义域关于0对称。","F(−x)=f(−x)g(−x)=−f(x)g(x)=−F(x)。"],"conclusion":"F(x)为奇函数。","pitfall":"奇乘偶为奇，不能把指数和误认为奇函数。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-CALC-9-55":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-CALC-9-55","method":"先把完全平方的平方根化成绝对值。","steps":["x²−2x+1=(x−1)²，所以y=∣x−1∣。","x≥1时x−1≥0，y=x−1；x<1时y=1−x。","图像是以(1,0)为顶点的V形，两侧斜率分别为−1和1。"],"conclusion":"y=x−1（x≥1）；y=1−x（x<1）。","pitfall":"√((x−1)²)=∣x−1∣，不能直接在全体实数上写成x−1。","caveat":""},"CQZSB-WORK-151-001":{"id":"CQZSB-WORK-151-001","method":"两个分母根式分别列严格不等式。","steps":["√(x+y)在分母，要求x+y>0。","√(x−y)也在分母，要求x−y>0。","两式等价于x>−y且x>y，即x>∣y∣。"],"conclusion":"定义域为{(x,y)∈ℝ²：x>∣y∣}。","pitfall":"两个条件取交集；等号对应分母为0，边界不能取。","caveat":""},"CQZSB-WORK-151-002":{"id":"CQZSB-WORK-151-002","method":"把根式与对数条件改写成半径平方的范围。","steps":["根式要求4−x²−y²≥0，即x²+y²≤4。","对数要求x²+y²−1>0，即x²+y²>1。","取交集为1<x²+y²≤4。"],"conclusion":"定义域为圆环区域1<x²+y²≤4，内边界不含、外边界包含。","pitfall":"乘积某因子为0也不能让未定义的对数变得有意义。","caveat":""},"CQZSB-WORK-151-003":{"id":"CQZSB-WORK-151-003","method":"先化简实数范围的立方根，再判断奇偶性。","steps":["对任意实数t有∛(t³)=t，故f(x)=(1−x²)sin⁵x。","1−x²为偶函数，sin⁵x为奇函数，定义域ℝ。","f(−x)=(1−x²)(−sin⁵x)=−f(x)。"],"conclusion":"f为奇函数。","pitfall":"实数立方根保留符号，不应化成|1−x²|。","caveat":""},"CQZSB-WORK-151-004":{"id":"CQZSB-WORK-151-004","method":"分别检查两个因子的奇偶性。","steps":["e⁻ˣ−eˣ=−(eˣ−e⁻ˣ)，所以第一个因子是奇函数。","arctan(−x)=−arctan x，第二个因子也是奇函数。","二者相乘后两负号抵消，f(−x)=f(x)。"],"conclusion":"f为偶函数，定义域ℝ。","pitfall":"奇函数的乘积是偶函数，和与积的奇偶规则不能混用。","caveat":""},"CQZSB-WORK-151-005":{"id":"CQZSB-WORK-151-005","method":"反解指数并用原值域确定新定义域。","steps":["原式要求x>−3，ln(x+3)能取所有实数，因此原值域为ℝ。","y−1=ln(x+3)，得x=e^(y−1)−3。","交换变量得到反函数。"],"conclusion":"反函数为y=e^(x−1)−3，定义域ℝ。","pitfall":"常数1在对数外，反解时要先减1再取指数。","caveat":""},"CQZSB-WORK-151-006":{"id":"CQZSB-WORK-151-006","method":"先将2ˣ整体解出，再取以2为底的对数。","steps":["设t=2ˣ>0，则y=t/(t+1)，所以0<y<1。","由y(t+1)=t得t=y/(1−y)。","x=log₂(y/(1−y))，交换变量。"],"conclusion":"反函数为y=log₂[x/(1−x)]，定义域(0,1)。","pitfall":"0、1只是原值域边界，均不能取得。","caveat":""},"CQZSB-WORK-152-007":{"id":"CQZSB-WORK-152-007","method":"把常用对数方程转为指数方程。","steps":["原真数x/(1−x)>0，得0<x<1，其取值可遍历正数，所以原值域ℝ。","10ʸ=x/(1−x)，整理为x(1+10ʸ)=10ʸ。","故x=10ʸ/(1+10ʸ)，再交换变量。"],"conclusion":"反函数为y=10ˣ/(1+10ˣ)，定义域ℝ。","pitfall":"分母是1+10ˣ，不能把解出的分式写反。","caveat":"题干未提供完整选项；来源标作A，但只能核实具体表达式。"},"CQZSB-WORK-152-008":{"id":"CQZSB-WORK-152-008","method":"反正弦限制与分母根式限制同时满足。","steps":["arcsin(x+y)要求−1≤x+y≤1。","√x在分母，要求x>0。","两条件取交集，也可写为x>0且−1−x≤y≤1−x。"],"conclusion":"定义域为{(x,y)：x>0，|x+y|≤1}。","pitfall":"反正弦的边界允许取等号，分母根式的边界不允许。","caveat":"完整选项缺失；来源标作B，具体区域可独立确认。"},"CQZSB-WORK-152-009":{"id":"CQZSB-WORK-152-009","method":"把内层x+a限制在原输入区间。","steps":["原区间[0,2a]作为非空定义域需a≥0。","要求0≤x+a≤2a，各端减a，得−a≤x≤a。"],"conclusion":"a≥0时，定义域为[−a,a]。","pitfall":"不要把输入加a误认为定义域也向右平移a。","caveat":"题干未显式说明a≥0；若a<0，所写原区间为空，不能按非空区间理解。"},"CQZSB-WORK-152-010":{"id":"CQZSB-WORK-152-010","method":"求内层分式在已知区间上的值域。","steps":["1≤x≤2时，7≤2x+5≤9，且分母为正。","取倒数后大小次序反向，得1/9≤1/(2x+5)≤1/7。","所以f所接受的输入范围为[1/9,1/7]。"],"conclusion":"按此类题的通常约定，f的定义域为[1/9,1/7]。","pitfall":"这是由复合定义域恢复内层值域，不能直接对区间取倒数而漏掉2x+5。","caveat":"严格说仅知该复合定义域不能排除f另在输入0处有定义，因为内层永远不取0；结论采用教材通常的恢复约定。"},"CQZSB-WORK-152-011":{"id":"CQZSB-WORK-152-011","method":"把各分段所覆盖的自变量区间求并集。","steps":["第一段覆盖(−∞,0]。","第二段覆盖(0,2)，第三段覆盖[2,5)。","0由第一段包含，2由第三段包含，三段无空隙。"],"conclusion":"定义域为(−∞,5)。","pitfall":"求定义域只看各段条件的并集，5在所有分段中均未包含。","caveat":""},"CQZSB-WORK-153-012":{"id":"CQZSB-WORK-153-012","method":"同一函数必须定义域和对应法则都相同。","steps":["A中arctan x∈(−π/2,π/2)，故tan(arctan x)=x，对任意实数成立。","B按ln((x+1)²)理解时定义域x≠−1，2ln(x+1)只允许x>−1。","C约分式排除x=1；D左式另允许x<−2而右式只允许x≥2。"],"conclusion":"选A：x与tan(arctan x)是同一函数。","pitfall":"化简后的表达式相等不能弥补原定义域的差异。","caveat":"B原记录ln(x+1)²排版有歧义；若指[ln(x+1)]²，则两式法则也不同，仍不影响选A。"},"CQZSB-WORK-153-013":{"id":"CQZSB-WORK-153-013","method":"三个限制逐一列出后取交集。","steps":["lg(x+1)要求x>−1。","1/√(x+2)要求x>−2。","arccos x要求−1≤x≤1；交集为−1<x≤1。"],"conclusion":"定义域为(−1,1]。","pitfall":"x=−1虽满足反余弦条件，但使对数真数为0。","caveat":"选项未保留；来源标作B，具体区间可确认。"},"CQZSB-WORK-153-014":{"id":"CQZSB-WORK-153-014","method":"要求对数内层的值位于原定义域。","steps":["f的输入必须满足0≤ln x≤1，同时ln x要求x>0。","指数函数递增，对不等式取指数得1≤x≤e。","所得区间自动满足x>0。"],"conclusion":"定义域为[1,e]。","pitfall":"ln x的值在[0,1]，并不表示x也在[0,1]。","caveat":"选项未保留；来源标作D，具体区间可确认。"},"CQZSB-WORK-153-015":{"id":"CQZSB-WORK-153-015","method":"逐项代入−x或用奇偶规则排除。","steps":["A的cos³x为偶函数；C的ln(x²+x⁴)在x≠0上为偶函数。","B含偶项x²和奇项sin x，且f(0)=0并不足以保证奇性，代入−x不等于−f(x)。","D代入−x并乘eˣ，得(1−eˣ)/(1+eˣ)=−f(x)。"],"conclusion":"选D，(eˣ−1)/(eˣ+1)为奇函数。","pitfall":"过原点只是奇函数的必要条件之一，不能据此判断B。","caveat":""},"CQZSB-WORK-153-016":{"id":"CQZSB-WORK-153-016","method":"用t=1/x把右端改写成t。","steps":["设t=1/x，原式要求x≠0且x≠1/2，所以t≠0,2。","右端=(3/t+1)/(2/t−1)=(3+t)/(2−t)。","改名后f(x)=(3+x)/(2−x)。"],"conclusion":"题设可确定f(x)=(3+x)/(2−x)，x≠0,2。","pitfall":"约去换元分母t后，不能据此补出t=0处原本未知的函数值。","caveat":"选项缺失，来源标作B；自然公式能延拓到0，但题设本身未确定f(0)。"},"CQZSB-WORK-155-019":{"id":"CQZSB-WORK-155-019","method":"按已核对原图的完整选项，用定义或反例判断。","steps":["A中奇函数加奇函数一般仍为奇函数，例如x+x=2x，并非偶函数。","B中偶函数若定义域含非零a，则f(a)=f(−a)，不一一对应，因而无反函数。","C可用偶函数x²无界反驳；D中若T为周期，则2T、3T也都是周期。"],"conclusion":"按通常非退化对称定义域的约定，选B。","pitfall":"反函数取决于一一对应性；周期并非只有最小正周期一个。","caveat":"完整选项已由原图核对。B需常规非退化定义域；定义域仅{0}时可逆，限制到单调支路后也可另求反函数。"},"CQZSB-WORK-155-021":{"id":"CQZSB-WORK-155-021","method":"计算f(−x)，判定图像对称性。","steps":["按指数函数常规条件a>0，分母aˣ+1始终为正。","f(−x)=−x(a⁻ˣ−1)/(a⁻ˣ+1)。","分式分子分母乘aˣ后，得−x(1−aˣ)/(1+aˣ)=f(x)。"],"conclusion":"f是偶函数，图像关于y轴对称。","pitfall":"代入−x后，外部x和分式各改变一次符号，两负相消。","caveat":"题干未写底数条件；按a>0讨论。a=1时图像为x轴，仍关于y轴对称。"},"CQZSB-WORK-155-022":{"id":"CQZSB-WORK-155-022","method":"对数移项后取指数。","steps":["原定义域为2x+1>0，即x>−1/2，值域ℝ。","y−2=ln(2x+1)，得2x+1=e^(y−2)。","解出x=(e^(y−2)−1)/2，再交换变量。"],"conclusion":"反函数为y=(e^(x−2)−1)/2，定义域ℝ。","pitfall":"减1发生在取指数之后，不能写成e^(x−3)/2。","caveat":""},"CQZSB-WORK-156-023":{"id":"CQZSB-WORK-156-023","method":"令分式输入为t，再把原变量解成t。","steps":["令t=(1−x)/(1+x)，要求x≠−1。","t+tx=1−x，故x=(1−t)/(1+t)，t≠−1。","原式f(t)=x，因此改名后得到相同形式的分式。"],"conclusion":"f(x)=(1−x)/(1+x)，x≠−1。","pitfall":"先交叉相乘再合并含x项，注意分母1+x不能为0。","caveat":""},"CQZSB-WORK-156-025":{"id":"CQZSB-WORK-156-025","method":"用平方非负给出全局上下界。","steps":["( ∣x∣−3 )²≥0，得x²+9≥6∣x∣。","因此∣x/(9+x²)∣≤1/6，对所有实数成立。","x=3取1/6，x=−3取−1/6，函数连续且值域为[−1/6,1/6]。"],"conclusion":"该函数有界，值域[−1/6,1/6]；来源称A。","pitfall":"有界指函数值有统一界限，与定义域是否无界无关。","caveat":"未保留完整选项，无法检查其他选项是否也描述其性质；该函数同时还是奇函数。"},"CQZSB-WORK-157-027":{"id":"CQZSB-WORK-157-027","method":"分母中的平方根必须严格为正。","steps":["要求5−x²−y²>0。","移项得x²+y²<5，即到原点的距离小于√5。"],"conclusion":"定义域为开圆盘{(x,y)：x²+y²<5}。","pitfall":"圆周上分母为0，不能把小于号写成小于等于号。","caveat":""},"CQZSB-WORK-157-028":{"id":"CQZSB-WORK-157-028","method":"用r²=x²+y²统一处理两个限制。","steps":["arccos(r²/4)要求−1≤r²/4≤1；因r²≥0，等价于r²≤4。","根式√(r²−2)要求r²≥2。","交集为2≤r²≤4。"],"conclusion":"定义域为2≤x²+y²≤4的闭圆环。","pitfall":"两个边界均可取，反余弦在1处以及平方根在0处均有定义。","caveat":""},"CQZSB-WORK-157-029":{"id":"CQZSB-WORK-157-029","method":"把g(x)整体代入分式的每个x位置。","steps":["g(x)=1−x，故f(g(x))=[1−(1−x)]/(1−x)。","分子化简为x，得到x/(1−x)。","f的输入不能为0，所以1−x≠0，即x≠1。"],"conclusion":"f[g(x)]=x/(1−x)，x≠1。","pitfall":"不能只替换分子而漏掉分母，复合后还须检查新分母。","caveat":""},"CQZSB-WORK-158-033":{"id":"CQZSB-WORK-158-033","method":"逐项核对原始定义域，选出法则也相等的一组。","steps":["B中ln(x³)要求x>0，与3ln x定义域相同，且对数幂公式给出相等值。","A的1/cot x还要求sin x≠0，故与tan x不同。","C左式要求x≥0，右式还允许x≤−1；D的(√x)²只允许x≥0。"],"conclusion":"选B：ln(x³)与3ln x是同一函数。","pitfall":"对数幂公式的使用须保留原始定义域，不能只比较化简式。","caveat":""},"CQZSB-WORK-159-034":{"id":"CQZSB-WORK-159-034","method":"分式、对数、根式的条件取交集。","steps":["1/(x−3)要求x≠3。","ln(x−1)要求x>1；分母√(x+1)要求x>−1。","合并得x>1且x≠3。"],"conclusion":"定义域为(1,3)∪(3,+∞)。","pitfall":"对数条件比根式条件更强，但仍须保留独立的排除点3。","caveat":"选项缺失，来源标作D；可确认具体区间。"},"CQZSB-WORK-159-035":{"id":"CQZSB-WORK-159-035","method":"分别求反正弦和平方根允许的区间。","steps":["−1≤(2x−1)/7≤1，化简得−3≤x≤4。","2x−x²=x(2−x)≥0，得0≤x≤2。","两区间交集为[0,2]。"],"conclusion":"定义域为[0,2]。","pitfall":"arcsin的真数允许等于±1，根号也允许为0。","caveat":"选项缺失，来源标作C；可确认具体区间。"},"CQZSB-WORK-159-036":{"id":"CQZSB-WORK-159-036","method":"解二次根式条件和指数对数条件。","steps":["2+x−x²=−(x−2)(x+1)≥0，得−1≤x≤2。","ln(eˣ−1)要求eˣ>1，即x>0。","取交集得到0<x≤2。"],"conclusion":"定义域为(0,2]。","pitfall":"x=0虽使根式有意义，却使对数真数为0，应排除。","caveat":""},"CQZSB-WORK-160-037":{"id":"CQZSB-WORK-160-037","method":"令t=eˣ+2，记录内层真实值域。","steps":["eˣ>0，所以t>2，而非t>3。","由t−2=eˣ，得x=ln(t−2)。","代入右端2ˣ+1，得f(t)=2^(ln(t−2))+1。"],"conclusion":"f(x)=2^(ln(x−2))+1，x>2。","pitfall":"指数eˣ在x为负数时仍可取(0,1)，不能误认为eˣ>1。","caveat":"来源写x>3与题干冲突；例如原变量x=−1时内层2+e⁻¹<3，仍有定义。"},"CQZSB-WORK-160-038":{"id":"CQZSB-WORK-160-038","method":"平方根非负决定反解后的支路与定义域。","steps":["原函数要求x≥1，√(x−1)≥0，故y≥1。","取log₂得log₂y=√(x−1)，再平方得x=(log₂y)²+1。","交换变量，保留新输入x≥1。"],"conclusion":"反函数为y=(log₂x)²+1，x≥1。","pitfall":"不能只用对数条件x>0；0<x<1对应负对数，不符合原平方根。","caveat":""},"CQZSB-WORK-160-039":{"id":"CQZSB-WORK-160-039","method":"先换元确定f，再求反函数和值域。","steps":["令t=1/x，x>1给出0<t<1；f(t)=(1/t)/(1−3/t)=1/(t−3)。","当0<t<1时，f(t)在(−1/2,−1/3)内。","由y=1/(t−3)解得t=3+1/y。"],"conclusion":"f⁻¹(x)=3+1/x，定义域(−1/2,−1/3)。","pitfall":"原条件x>1限制了f的定义域，不能把反函数定义域写成x≠0。","caveat":""},"CQZSB-B2-D11-BF-MATH-FUNC-SEL-1-01":{"id":"CQZSB-B2-D11-BF-MATH-FUNC-SEL-1-01","method":"反余弦的输入必须在[−1,1]。","steps":["列出−1≤x−4≤1。","各端加4得3≤x≤5，两个端点分别对应arccos(−1)和arccos1，均有意义。"],"conclusion":"定义域[3,5]，选B。","pitfall":"限制的是x−4而不是x本身；端点可保留。","caveat":""},"CQZSB-B2-V190-177":{"id":"CQZSB-B2-V190-177","method":"有理分式只需排除分母零点。","steps":["分母x−2不能为0，所以x≠2。","其余实数均可代入，分成小于2和大于2的两个区间。"],"conclusion":"定义域为(−∞,2)∪(2,+∞)，选C。","pitfall":"不能只保留分母为正的部分，负分母同样有意义。","caveat":""},"CQZSB-B2-V190-178":{"id":"CQZSB-B2-V190-178","method":"实数平方根要求被开方数非负。","steps":["x−1≥0，解得x≥1。","x=1时函数值为0，平方根并未出现在分母，故端点允许。"],"conclusion":"定义域为[1,+∞)，选C。","pitfall":"根式不在分母时允许根号内为0，勿误写开区间。","caveat":""},"CQZSB-B2-V190-179":{"id":"CQZSB-B2-V190-179","method":"自然对数要求真数严格为正。","steps":["列出x−3>0。","解得x>3；x=3时真数为0，对数无定义。"],"conclusion":"定义域为(3,+∞)，选A。","pitfall":"ln0不存在，不能保留x=3。","caveat":""},"CQZSB-B2-V190-180":{"id":"CQZSB-B2-V190-180","method":"根式、对数真数及分母非零三项同时检查。","steps":["√(2−x)要求x≤2。","ln x要求x>0；又因其在分母，须ln x≠0，即x≠1。","合并为0<x≤2且x≠1。"],"conclusion":"定义域为(0,1)∪(1,2]，选B。","pitfall":"x=2可取，x=1不可取，两个端点的限制来源不同。","caveat":""},"CQZSB-B2-V190-181":{"id":"CQZSB-B2-V190-181","method":"先限制反正弦输入，再排除分母为0。","steps":["−1≤x−1≤1，得0≤x≤2。","arcsin(x−1)=0当且仅当x−1=0，即x=1。","从闭区间[0,2]中剔除1。"],"conclusion":"定义域为[0,1)∪(1,2]，选B。","pitfall":"反正弦在±1处分别为±π/2，并非0，故0和2都可保留。","caveat":""},"CQZSB-B2-V190-182":{"id":"CQZSB-B2-V190-182","method":"因式分解后的分母逐因子排零。","steps":["分母x(x+2)≠0，要求x≠0且x≠−2。","按两个排除点把实轴分成三个开区间。"],"conclusion":"定义域为(−∞,−2)∪(−2,0)∪(0,+∞)，选A。","pitfall":"分母允许为负，不能用x(x+2)>0代替非零条件。","caveat":""},"CQZSB-B2-V190-183":{"id":"CQZSB-B2-V190-183","method":"用定义域与恒等变形双重检查。","steps":["C中∣x∣=√(x²)对所有实数成立，两者定义域均为ℝ。","A左式允许负x，右式不允许；B右式还排除sin x=0的点。","D左式要求∣x∣>2，右式要求x>2，定义域不同。"],"conclusion":"选C：∣x∣与√(x²)是同一函数。","pitfall":"平方根的结果是绝对值，函数相同还必须有相同定义域。","caveat":""},"CQZSB-B2-V190-184":{"id":"CQZSB-B2-V190-184","method":"自变量名称无关紧要，定义域与法则才决定函数。","steps":["C中的x+3与t+3均把任意实数加3，定义域和对应关系完全一致。","A的ln(x²)允许x<0，2ln x不允许。","B的x³/x=x²（x≠0），并不等于x；D左式要求x≥0而右式定义于ℝ。"],"conclusion":"选C：f(x)=x+3与f(t)=t+3。","pitfall":"x和t只是自变量的记号，换字母不会改变函数。","caveat":""},"CQZSB-B2-V190-185":{"id":"CQZSB-B2-V190-185","method":"内层表达式必须落在(0,1)。","steps":["列出0<x−2<1。","各端加2得2<x<3。"],"conclusion":"定义域为(2,3)，选B。","pitfall":"两个端点都是原函数禁用的输入，平移后仍为开端点。","caveat":""},"CQZSB-B2-V190-186":{"id":"CQZSB-B2-V190-186","method":"对内层一次式列双边不等式。","steps":["要求0≤3x−2≤2。","各端加2得2≤3x≤4，再除以正数3。","得到2/3≤x≤4/3。"],"conclusion":"定义域为[2/3,4/3]，选D。","pitfall":"原定义域的端点可取，新区间也必须保留闭端点。","caveat":""},"CQZSB-B2-V190-187":{"id":"CQZSB-B2-V190-187","method":"先求f的真实输入区间再平移。","steps":["f(x+1)的变量x∈[1,2]，所以f的输入x+1∈[2,3]。","f(x−1)要求2≤x−1≤3。","各端加1，得3≤x≤4。"],"conclusion":"定义域为[3,4]，选C。","pitfall":"题设给的是f(x+1)的定义域，不能直接当成f的定义域。","caveat":""},"CQZSB-B2-V190-188":{"id":"CQZSB-B2-V190-188","method":"通过内层范围恢复f的定义域。","steps":["−1<x<1时，2<x+3<4，故f的输入范围为(2,4)。","对f(x−3)列出2<x−3<4。","各端加3得5<x<7。"],"conclusion":"定义域为(5,7)，选B。","pitfall":"两次平移需分别处理，不能只把(−1,1)平移3。","caveat":""},"CQZSB-B2-V190-189":{"id":"CQZSB-B2-V190-189","method":"逐项代入−x并检查对称定义域。","steps":["B的分母eˣ+1>0，定义域ℝ；f(−x)=(1−eˣ)/(1+eˣ)=−f(x)。","A的内部x²+x⁴为偶式，D由两个偶因子组成，均为偶函数。","C在x=0处为1，不能是奇函数。"],"conclusion":"选B，(eˣ−1)/(eˣ+1)为奇函数。","pitfall":"复合函数奇偶性取决于整体代入结果，不能只看到sin就判奇。","caveat":""},"CQZSB-B2-V190-190":{"id":"CQZSB-B2-V190-190","method":"构造式代入−x，判断是否恒成立。","steps":["令F(x)=f(x)+f(−x)。","F(−x)=f(−x)+f(x)=F(x)，且已知f定义域ℝ。","A一般为奇函数；取f(x)=1可使C、D均变成x，说明它们不一定为偶函数。"],"conclusion":"选B：f(x)+f(−x)必为偶函数。","pitfall":"题目对任意f成立，不能把某个特殊f的性质当成一般结论。","caveat":""},"CQZSB-B2-V190-191":{"id":"CQZSB-B2-V190-191","method":"直接代入−x并消去负指数。","steps":["分母eˣ+1>0，定义域为关于0对称的ℝ。","f(−x)=(e⁻ˣ−1)/(e⁻ˣ+1)。","分子分母同乘eˣ，得(1−eˣ)/(1+eˣ)=−f(x)。"],"conclusion":"该函数是奇函数，选B。","pitfall":"不能因分子含−1就说非奇非偶，必须计算整体变化。","caveat":""},"CQZSB-B2-V190-192":{"id":"CQZSB-B2-V190-192","method":"求一次内层在给定闭区间上的值域。","steps":["x∈[0,1]时，3x+1单调递增。","左端取1，右端取4，且中间值均能取得。"],"conclusion":"f(x)的定义域为[1,4]。","pitfall":"已知的是复合函数的自变量区间，需要把整个3x+1映射过去。","caveat":""},"CQZSB-B2-V190-193":{"id":"CQZSB-B2-V190-193","method":"根据−3所在区间选用对应分段。","steps":["−3≤0，应使用e^(x²)+2x。","代入得(−3)²=9，2×(−3)=−6。","因此f(−3)=e⁹−6。"],"conclusion":"f(−3)=e⁹−6。","pitfall":"指数是x²，先平方得到9，不能把e^(x²)写成e⁻⁹。","caveat":""},"CQZSB-B2-V190-194":{"id":"CQZSB-B2-V190-194","method":"让内层输入恰好等于所求的2。","steps":["设2x−1=2，解得x=3/2。","把x=3/2代入右端x²+1，得9/4+1=13/4。"],"conclusion":"f(2)=13/4。","pitfall":"不能直接在右端代入2，因为左边的输入是2x−1。","caveat":""},"CQZSB-B2-V190-195":{"id":"CQZSB-B2-V190-195","method":"以t=x+1换元或配方。","steps":["x²+2x=(x+1)²−1。","令t=x+1，t能遍历ℝ，于是f(t)=t²−1。"],"conclusion":"f(x)=x²−1，x∈ℝ。","pitfall":"内层加1后，右端应以x+1整体表示，不能直接去掉左边的+1。","caveat":""},"CQZSB-B2-V190-196":{"id":"CQZSB-B2-V190-196","method":"令t=x−1，将原变量全部换成t+1。","steps":["令t=x−1，则x=t+1。","f(t)=(t+1)³−1=t³+3t²+3t+1−1。","把t改名为x即得解析式。"],"conclusion":"f(x)=x³+3x²+3x，x∈ℝ。","pitfall":"立方展开不能遗漏3t²和3t两项。","caveat":""},"CQZSB-B2-V190-197":{"id":"CQZSB-B2-V190-197","method":"把对数方程转为指数方程后反解。","steps":["原函数要求2x>0，即x>0，值域为ℝ。","y=ln(2x)给出2x=eʸ，故x=eʸ/2。","交换x、y。"],"conclusion":"反函数为y=eˣ/2，x∈ℝ。","pitfall":"ln(2x)中的2是乘在原变量外，反解后为除以2。","caveat":""},"CQZSB-B2-V190-198":{"id":"CQZSB-B2-V190-198","method":"先求值域，再通过对数反解。","steps":["e^(3x)>0，所以原值域为(−4,+∞)。","由y+4=e^(3x)得3x=ln(y+4)。","交换变量后得到反函数及输入范围。"],"conclusion":"反函数为y=ln(x+4)/3，x>−4。","pitfall":"反函数中的对数真数为x+4，不能写成ln x+4。","caveat":""},"CQZSB-B2-V190-199":{"id":"CQZSB-B2-V190-199","method":"先检查原函数是否一一对应。","steps":["题干没有限制x，4sin(3x−1)在ℝ上为周期函数，不同输入可能给出同一输出。","例如x=1/3与x=(π+1)/3均使正弦为0，因此在ℝ上没有反函数。","若另限制3x−1∈[−π/2,π/2]，才可解得x=(arcsin(y/4)+1)/3。"],"conclusion":"按现有题干不存在反函数；主值支路条件下才有y=(arcsin(x/4)+1)/3，x∈[−4,4]。","pitfall":"不能把arcsin(sin t)=t用于任意实数t。","caveat":"来源给出的公式隐含单调区间，题干未提供该必要限制。"},"CQZSB-B2-V190-200":{"id":"CQZSB-B2-V190-200","method":"移去对数外常数，再取指数。","steps":["原定义域x>3，原值域ℝ。","由y−2=ln(x−3)得x−3=e^(y−2)。","解得x=e^(y−2)+3，再交换变量。"],"conclusion":"反函数为y=e^(x−2)+3，x∈ℝ。","pitfall":"原式中的−3在反解后变成+3，外部+2则变成指数中的−2。","caveat":""},"CQZSB-B2-V190-201":{"id":"CQZSB-B2-V190-201","method":"沿v、u、f的顺序代入。","steps":["先有v=sin x，再得u=eᵛ=e^(sin x)>0。","最后f(u)=√u，所以复合结果是√(e^(sin x))。","指数始终为正，平方根对所有实数x均有意义。"],"conclusion":"复合函数为y=√(e^(sin x))=e^((sin x)/2)，x∈ℝ。","pitfall":"题中f(u)表示外层法则，不能只把字母u改成x就停在√x。","caveat":""},"CQZSB-B2-V190-202":{"id":"CQZSB-B2-V190-202","method":"从内层逐层求出x=0时的数值。","steps":["x=0时sin0+cos0=1，因此v=e。","u=ln v=ln e=1。","最外层f(u)=u²=1。"],"conclusion":"复合函数在0处的值为1。","pitfall":"先合成或逐层计算均可，但不能把最外层u²误作v²。","caveat":""},"CQZSB-B2-V190-203":{"id":"CQZSB-B2-V190-203","method":"按线性、平方根、对数、指数四层拆分。","steps":["先令w=3x−1，再令v=√w。","令u=ln v，最后y=2ᵘ。","ln v要求v>0，从而3x−1>0，即x>1/3。"],"conclusion":"可分解为y=2ᵘ，u=ln v，v=√w，w=3x−1；x>1/3。","pitfall":"根式本身允许0，但其结果作为对数真数时必须严格大于0。","caveat":""},"CQZSB-B2-V190-204":{"id":"CQZSB-B2-V190-204","method":"对数分母与平方根的三个条件取交集。","steps":["ln(x+3)存在要求x>−3；作为分母还要求ln(x+3)≠0，即x≠−2。","√(9−x²)要求−3≤x≤3。","合并后为−3<x≤3且x≠−2。"],"conclusion":"定义域为(−3,−2)∪(−2,3]。","pitfall":"x=−3使对数无定义，x=−2使分母为0，必须分别排除。","caveat":""},"CQZSB-B2-V190-205":{"id":"CQZSB-B2-V190-205","method":"设eʸ为真数，交叉相乘反解。","steps":["原真数(x−1)/(x+1)>0，故原定义域为(−∞,−1)∪(1,+∞)。","eʸ(x+1)=x−1，得x=(1+eʸ)/(1−eʸ)。","原函数不取0，且正、负实数均能取到，故反函数输入x≠0。"],"conclusion":"反函数为y=(1+eˣ)/(1−eˣ)，x∈(−∞,0)∪(0,+∞)。","pitfall":"对数的输出不必为正，本题值域包含所有非零实数。","caveat":""},"CQZSB-B2-V190-206":{"id":"CQZSB-B2-V190-206","method":"利用x≤0选择平方根的负号。","steps":["在x≤0时，y=1/(1+x²)的值域为(0,1]。","由1/y=1+x²得到x²=1/y−1。","原变量x≤0，所以x=−√(1/y−1)，交换变量。"],"conclusion":"反函数为y=−√(1/x−1)，定义域(0,1]。","pitfall":"平方后反解有±两支，原定义域决定取负号。","caveat":""},"CQZSB-B2-V190-207":{"id":"CQZSB-B2-V190-207","method":"令t=ln x，将x改成eᵗ。","steps":["ln x要求x>0，t=ln x能遍历ℝ。","x=eᵗ，故右端x²+3x变为e^(2t)+3eᵗ。","因此f(t)=e^(2t)+3eᵗ。"],"conclusion":"f(x)=e^(2x)+3eˣ，x∈ℝ。","pitfall":"x²换元后是e^(2t)，不能写成e^(t²)。","caveat":""},"CQZSB-B2-V190-208":{"id":"CQZSB-B2-V190-208","method":"将原自变量用新输入加1表示。","steps":["令t=x−1，故x=t+1。","f(t)=2(t+1)²+4(t+1)−1。","展开合并为2t²+8t+5。"],"conclusion":"f(x)=2x²+8x+5。","pitfall":"换元时右端所有x都要替换，包括一次项4x。","caveat":""},"CQZSB-B2-V190-209":{"id":"CQZSB-B2-V190-209","method":"让左边函数的输入等于2。","steps":["由x−1=2，解得原变量x=3。","代入右边得到2×3²+4×3−1=18+12−1=29。"],"conclusion":"f(2)=29。","pitfall":"不能把原式右边的x直接换成2，左边输入是x−1。","caveat":""},"CQZSB-B2-V190-210":{"id":"CQZSB-B2-V190-210","method":"分母根式严格大于0。","steps":["9−x²>0等价于x²<9。","因此−3<x<3；两个端点都会导致分母为0。"],"conclusion":"定义域为(−3,3)。","pitfall":"根式在分母中，不能把严格不等式放宽为≥0。","caveat":""},"CQZSB-B2-V190-211":{"id":"CQZSB-B2-V190-211","method":"反正弦和对数条件取交集。","steps":["arcsin(x−3)要求−1≤x−3≤1，得到2≤x≤4。","ln(x−2)要求x>2。","交集为2<x≤4。"],"conclusion":"定义域为(2,4]。","pitfall":"2因对数被排除，4仍使arcsin真数为1，可以保留。","caveat":""},"CQZSB-B2-V190-214":{"id":"CQZSB-B2-V190-214","method":"以t=1−1/x换元并保留不可达点。","steps":["令t=1−1/x，则x=1/(1−t)，t≠1。","原分母1−3x≠0要求x≠1/3，对应t≠−2。","右边=[1/(1−t)]/[1−3/(1−t)]=−1/(t+2)。"],"conclusion":"f(x)=−1/(x+2)，题设确定的范围为x≠−2,1。","pitfall":"约分不会确定原内层永远取不到的输入1处的f值。","caveat":"来源只给公式；自然延拓可包含1，但题设本身未确定f(1)。"},"CQZSB-B2-V190-215":{"id":"CQZSB-B2-V190-215","method":"使用sin²x=1−cos²x消去另一三角函数。","steps":["1−2sin²x=1−2(1−cos²x)=2cos²x−1。","令t=cos x，t的取值范围为[−1,1]。","因此f(t)=2t²−1。"],"conclusion":"f(x)=2x²−1，−1≤x≤1。","pitfall":"题设只给出余弦输入对应的函数值，不能自动断言公式在整个ℝ上成立。","caveat":""},"CQZSB-B2-V190-216":{"id":"CQZSB-B2-V190-216","method":"立方根在ℝ上严格递增，可直接立方反解。","steps":["原函数定义域为ℝ，值域也为ℝ。","y=∛(x+2)两边立方，得y³=x+2。","解出x=y³−2，再交换变量。"],"conclusion":"反函数为y=x³−2，x∈ℝ。","pitfall":"奇次根允许负输入，无须添加x≥−2的限制。","caveat":""},"CQZSB-B2-V190-217":{"id":"CQZSB-B2-V190-217","method":"先检查正弦函数是否有单调区间限制。","steps":["题干未限制x，3sin4x在ℝ上周期为π/2。","x=0和x=π/4都使函数值为0，因此原函数不是一一对应，不能在ℝ上求反函数。","若另规定x∈[−π/8,π/8]，则4x位于正弦主值区间，可反解得y=arcsin(x/3)/4。"],"conclusion":"按现有题干没有反函数；补充主值单调区间后为y=arcsin(x/3)/4，x∈[−3,3]。","pitfall":"不能看到正弦就直接写反正弦，须先确认单调区间。","caveat":"原题缺少必要的定义域限制，答案留空，不能替题干选择支路。"},"CQZSB-B2-V190-218":{"id":"CQZSB-B2-V190-218","method":"把内函数sin x作为外函数的整体输入。","steps":["f(t)=1+t²。","令t=g(x)=sin x，得到f(g(x))=1+(sin x)²。"],"conclusion":"f[g(x)]=1+sin²x，定义域ℝ。","pitfall":"f(g(x))表示复合，不能写成(1+x²)sin x。","caveat":""},"CQZSB-B2-V190-219":{"id":"CQZSB-B2-V190-219","method":"识别线性、正弦、平方三层。","steps":["最内层令v=2x+1。","中层令u=sin v，最外层令y=u²。","正弦和平方均对全部实数有意义，定义域ℝ。"],"conclusion":"分解为y=u²，u=sin v，v=2x+1。","pitfall":"sin²(2x+1)是整个正弦值平方，不是sin((2x+1)²)。","caveat":""},"CQZSB-B2-V190-221":{"id":"CQZSB-B2-V190-221","method":"逐项比较定义域和对应值。","steps":["D中实数立方根满足∛(x³)=x，且两式定义域均为ℝ。","A中√(x²)=∣x∣，负x时与x不同。","B的(√x)²要求x≥0，C的e^(ln x)要求x>0，均与恒等函数x的定义域不同。"],"conclusion":"选D：∛(x³)与x是同一函数。","pitfall":"偶次根和奇次根的化简不同，前者要绝对值，后者保留原符号。","caveat":""},"CQZSB-B2-V190-222":{"id":"CQZSB-B2-V190-222","method":"用恒等式并核对全部实数是否都能代入。","steps":["B中sin²x+cos²x=1对所有实数成立，因此与常函数1相同。","A的x/x排除0；C的e^(ln x)只允许x>0。","D左式只在x>0有意义，右式ln(eˣ)=x定义于ℝ。"],"conclusion":"选B：1与sin²x+cos²x为同一函数。","pitfall":"即使约分或指数对数相消，也不能补回原式中被排除的输入。","caveat":""},"CQZSB-B2-V190-223":{"id":"CQZSB-B2-V190-223","method":"利用反三角函数的主值和特殊角。","steps":["sin(π/6)=1/2，所以arcsin(1/2)=π/6，A错。","cos(π/6)=√3/2，故arccos(√3/2)=π/6，B错。","tan(π/4)=1且π/4在反正切主值区间，故arctan1=π/4；arcsin1=π/2，D错。"],"conclusion":"选C：arctan1=π/4。","pitfall":"π/6与π/3的正弦、余弦值容易混淆，可先写特殊角函数值。","caveat":""},"CQZSB-B2-V190-224":{"id":"CQZSB-B2-V190-224","method":"分子分母分别判断奇偶，并检查对称定义域。","steps":["C的x²、cos x、∣x∣均为偶函数，sin x为奇函数，分式定义域x≠kπ（k∈ℤ）关于0对称。","所以C代入−x后仅分母变号，整体为奇函数。","A为偶函数；B同时含非零偶项与奇项；D分子分母均为偶函数，为偶函数。"],"conclusion":"选C：x²cos x·∣x∣/sin x是奇函数。","pitfall":"∣x∣是偶函数，不能因其中出现x就认为它是奇函数。","caveat":""},"CQZSB-B2-V190-225":{"id":"CQZSB-B2-V190-225","method":"交换x与−x，检查构造式的对称性。","steps":["设F(x)=f(x)+f(−x)，则F(−x)=f(−x)+f(x)=F(x)。","B的差式在换号后变为相反数。","cot、sin、tan均为奇函数，相应复合sin(cot x)、tan(sin x)为奇函数，其自然定义域均对称。"],"conclusion":"按自然对称定义域理解，选A：f(x)+f(−x)。","pitfall":"对任意f的结论要以f(x)和f(−x)都存在为前提。","caveat":"题干未交代f的定义域；A应取D∩(−D)，并假设该共同定义域非空。"},"CQZSB-B2-V190-226":{"id":"CQZSB-B2-V190-226","method":"从外层对数向内逐层列正值条件。","steps":["外层ln要求ln x>0。","由ln x>0得x>1，这也自动保证内层ln x有意义。"],"conclusion":"定义域为(1,+∞)。","pitfall":"只写x>0仅保证内层对数存在，还没有满足外层真数为正。","caveat":""},"CQZSB-B2-V190-227":{"id":"CQZSB-B2-V190-227","method":"让指数内层落在[0,1]。","steps":["需0≤eˣ≤1。","eˣ对所有实数恒大于0，所以下界自动满足。","由eˣ≤1=e⁰及指数递增性得x≤0。"],"conclusion":"定义域为(−∞,0]。","pitfall":"指数永远不等于0，但这不会要求x有有限左端点。","caveat":""},"CQZSB-B2-V190-228":{"id":"CQZSB-B2-V190-228","method":"先将右端化成sin x的多项式，再代入x³。","steps":["1−cos2x=2sin²x，令t=sin x，得f(t)=2t²，−1≤t≤1。","求f(x³)需−1≤x³≤1，由立方递增得−1≤x≤1。","代入得到f(x³)=2(x³)²=2x⁶。"],"conclusion":"f(x³)=2x⁶，题设确定范围为x∈[−1,1]。","pitfall":"sin x的值域有限，公式不能无依据地扩展到全部输入。","caveat":""},"CQZSB-B2-V190-229":{"id":"CQZSB-B2-V190-229","method":"交叉相乘解出原自变量。","steps":["由y(1+2x)=1−3x，整理为(2y+3)x=1−y。","故x=(1−y)/(2y+3)，要求y≠−3/2。","原函数x≠−1/2，原值域为除−3/2外的所有实数，交换变量即得反函数。"],"conclusion":"反函数为y=(1−x)/(2x+3)，x≠−3/2。","pitfall":"反函数的禁用输入来自原值域，不能照抄原函数的x≠−1/2。","caveat":""},"CQZSB-B2-V190-230":{"id":"CQZSB-B2-V190-230","method":"先减去外部常数，再取指数。","steps":["原函数要求x>−2，且ln(x+2)的值域为ℝ。","y−3=ln(x+2)，所以x=e^(y−3)−2。","交换自变量与因变量，反函数输入遍历ℝ。"],"conclusion":"反函数为y=e^(x−3)−2，x∈ℝ。","pitfall":"原括号内+2在反解时移到外部成为−2。","caveat":""},"CQZSB-B2-V190-231":{"id":"CQZSB-B2-V190-231","method":"把加1、根号、正弦、对数、平方按内外顺序拆开。","steps":["依次令t=x+1，w=√t，v=sin w，u=ln v，最后y=u²。","根式需x≥−1，对数还需sin√(x+1)>0。","等价地，√(x+1)位于(2kπ,(2k+1)π)，k=0,1,2,…。"],"conclusion":"分解为y=u²，u=ln v，v=sin w，w=√t，t=x+1。","pitfall":"ln²v表示(ln v)²，不能误写ln(v²)；真数仍必须为正。","caveat":"分解并不免除定义域限制：x属于各区间((2kπ)²−1,((2k+1)π)²−1)，k≥0。"},"CQZSB-B2-V190-232":{"id":"CQZSB-B2-V190-232","method":"利用共轭因子的乘积为1证明奇性。","steps":["√(1+x²)>∣x∣，故x+√(1+x²)>0，对所有实数有定义。","[√(1+x²)−x][√(1+x²)+x]=1。","f(−x)=ln(√(1+x²)−x)=ln[1/(√(1+x²)+x)]=−f(x)。"],"conclusion":"该函数是奇函数，定义域ℝ。","pitfall":"对数真数含根式时不能直接逐项取对数，关键是共轭相乘为1。","caveat":""},"CQZSB-B2-V190-233":{"id":"CQZSB-B2-V190-233","method":"从内到外求值并重新判断分段。","steps":["∣800∣>1，所以f(800)=1/800。","∣1/800∣≤1，外层应使用函数值为0的分段。","因此f(f(800))=f(1/800)=0。"],"conclusion":"f[f(800)]=0，选D。","pitfall":"内层变成很小的数后，外层分段也变了，不能再取倒数回到800。","caveat":""},"CQZSB-B2-V190-234":{"id":"CQZSB-B2-V190-234","method":"指数分式、分母根式、反正弦条件取交集。","steps":["e^(1/x)要求x≠0。","1/√(4−x²)要求4−x²>0，即−2<x<2。","arcsin(x−1)要求−1≤x−1≤1，即0≤x≤2；三者交集为0<x<2。"],"conclusion":"定义域为(0,2)，选D。","pitfall":"0被指数中的分母排除，2被根式分母排除，不能仅用反正弦的闭区间。","caveat":""},"CQZSB-B2-V190-235":{"id":"CQZSB-B2-V190-235","method":"把x换成−x，比较函数值。","steps":["设H(x)=f(x)+f(−x)，则H(−x)=f(−x)+f(x)=H(x)","A中x²cot x为奇函数，外层sin仍使它为奇函数","C换元得原式相反数，D利用两真数乘积为1也得奇函数"],"conclusion":"B为偶函数，选B。","pitfall":"抽象函数和的自然定义域应取f(x)、f(−x)都存在的交集。","caveat":""},"CQZSB-B2-V190-236":{"id":"CQZSB-B2-V190-236","method":"分别求两个三角项的周期，再取公共周期。","steps":["cos(x/3)的最小正周期为6π，sin(x/2)的为4π","令T=6mπ=4nπ，最小正整数解为m=2、n=3，得T=12π"],"conclusion":"最小正周期12π，按通常题意选C；24π也是周期。","pitfall":"振幅2、3不影响周期。","caveat":"若题目仅说“周期”而非“最小正周期”，C、D都符合，单选表述不严谨。"},"CQZSB-B2-V190-237":{"id":"CQZSB-B2-V190-237","method":"先用正弦值域限制x，再讨论反正弦分支。","steps":["由−1≤1−x²≤1得0≤x²≤2，所以|x|≤√2","取主值时φ(x)=arcsin(1−x²)","一般解为φ(x)=nπ+(−1)ⁿarcsin(1−x²)，n为整数，可随x选取"],"conclusion":"主值解为arcsin(1−x²)，最大实数定义域[−√2,√2]。","pitfall":"sin不是在整个实数轴上的一一映射。","caveat":"未限制φ的值域，φ并不唯一；原答案只是主值解。"},"CQZSB-B2-V190-238":{"id":"CQZSB-B2-V190-238","method":"按内层x²的正负选择外层分段。","steps":["x²≥0且仅当x=0时等于0","x=0时用e⁰=1，x≠0时x²>0，用负输入值一支得−x²"],"conclusion":"f(x²)=1（x=0）；−x²（x≠0），定义域ℝ。","pitfall":"分段条件判断的是传入f的x²，而不是原x。","caveat":""},"CQZSB-B2-V190-239":{"id":"CQZSB-B2-V190-239","method":"先算内层，再由其符号选外层公式。","steps":["x≤0时f(x)=eˣ>0，因此f(f(x))=−eˣ","x>0时f(x)=−x<0，因此f(f(x))=e⁻ˣ"],"conclusion":"f(f(x))=−eˣ（x≤0）；e⁻ˣ（x>0）。","pitfall":"内层与外层不一定使用同一分支，x=0时结果是−1。","caveat":""},"CQZSB-B2-V190-240":{"id":"CQZSB-B2-V190-240","method":"把g的分段继续按其输出是否大于0拆分。","steps":["x≤0时g(x)=x≤0，故f(g(x))=eˣ","0<x≤1时g(x)=x−1≤0，故结果为e^(x−1)","x>1时g(x)=x−1>0，故结果为1−x"],"conclusion":"依次为eˣ（x≤0）、e^(x−1)（0<x≤1）、1−x（x>1）。","pitfall":"x=1传入的是0，应代入指数支，结果1。","caveat":""},"CQZSB-PAPER-161-01":{"id":"CQZSB-PAPER-161-01","method":"两个函数项必须同时有意义。","steps":["0≤x+2≤2给出−2≤x≤0","0≤x+1≤2给出−1≤x≤1","两区间取交集得到[−1,0]"],"conclusion":"定义域为[−1,0]。","pitfall":"和、差的定义域取交集，不能取并集。","caveat":""},"CQZSB-PAPER-161-02":{"id":"CQZSB-PAPER-161-02","method":"按复合顺序从内到外代入。","steps":["g(π/4)=tan(π/4)=1","f(1)=1³+3×1−2=2"],"conclusion":"f(g(π/4))=2。","pitfall":"先求g的函数值，再把所得数传入f。","caveat":""},"CQZSB-PAPER-161-03":{"id":"CQZSB-PAPER-161-03","method":"同时检查内外两层分母。","steps":["内层f(x)=1/(1+x)要求x≠−1","外层要求1+1/(1+x)≠0，即(x+2)/(x+1)≠0，故x≠−2"],"conclusion":"定义域为ℝ去掉−1、−2；复合式为(x+1)/(x+2)。","pitfall":"化简后看不见的x=−1仍不能补回。","caveat":""},"CQZSB-PAPER-161-04":{"id":"CQZSB-PAPER-161-04","method":"交换变量前先解出指数项并确定原值域。","steps":["tan y=(2ˣ+1)/2，故2ˣ=2tan y−1","原函数满足arctan(1/2)<y<π/2","解得x=log₂(2tan y−1)，再交换x、y"],"conclusion":"反函数y=log₂(2tan x−1)，定义域(arctan(1/2),π/2)。","pitfall":"反函数定义域必须等于原函数值域，不能遗漏主值范围。","caveat":""},"CQZSB-PAPER-161-05":{"id":"CQZSB-PAPER-161-05","method":"利用两个奇函数相乘。","steps":["定义域ℝ关于原点对称","f(−x)=(−x)³sin(−x)=(−x³)(−sin x)=x³sin x"],"conclusion":"f为偶函数。","pitfall":"一个负号来自三次方，另一个来自sin，必须同时处理。","caveat":""},"CQZSB-PAPER-161-06":{"id":"CQZSB-PAPER-161-06","method":"先求对数定义域，再取负自变量。","steps":["(1+x)/(1−x)>0给出−1<x<1","f(−x)=ln((1−x)/(1+x))=−ln((1+x)/(1−x))"],"conclusion":"定义域(−1,1)，f为奇函数。","pitfall":"只有真数为正时才能使用ln(1/u)=−ln u。","caveat":""},"CQZSB-PAPER-161-07":{"id":"CQZSB-PAPER-161-07","method":"区分平方作用于输入还是函数值。","steps":["f(g(x))=f(sin x)=(sin x)²","g(f(x))=g(x²)=sin(x²)，两者定义域都是ℝ"],"conclusion":"f(g(x))=sin²x，g(f(x))=sin(x²)。","pitfall":"sin²x与sin(x²)是不同函数，复合次序不可交换。","caveat":""},"CQZSB-PAPER-161-08":{"id":"CQZSB-PAPER-161-08","method":"利用反正弦的主值范围解方程。","steps":["原定义域−2≤x≤2，值域−π/2≤y≤π/2","由y=arcsin(x/2)得x=2sin y","交换变量得到反函数"],"conclusion":"反函数y=2sin x，定义域[−π/2,π/2]。","pitfall":"不能把反函数的定义域扩成ℝ，否则失去一一对应。","caveat":""},"CQZSB-PAPER-162-09":{"id":"CQZSB-PAPER-162-09","method":"分母根式与对数的条件取交集。","steps":["49−x²>0，所以−7<x<7","3x−6>0，所以x>2","交集为(2,7)"],"conclusion":"定义域(2,7)，选B。","pitfall":"根号在分母上，根内必须严格大于0。","caveat":""},"CQZSB-PAPER-162-10":{"id":"CQZSB-PAPER-162-10","method":"把每段允许的x区间取并集。","steps":["第一段允许[−π/2,0)，第二段允许[0,π]","0由第二段取到，左右端点也都有定义"],"conclusion":"定义域[−π/2,π]，选B。","pitfall":"分段函数的各段定义区间取并集，0并没有缺失。","caveat":""},"CQZSB-PAPER-162-11":{"id":"CQZSB-PAPER-162-11","method":"同时比较定义域和对应法则。","steps":["A左式排除1，右式不排除，定义域不同","B中√(x²)=|x|，负数处不等于x","C中ln(x²)允许负x，而2ln x只允许正x","D用sin²x+cos²x=1，两边都在ℝ上定义"],"conclusion":"相同函数为D。","pitfall":"代数化简后相等并不足够，还要有相同定义域。","caveat":""},"CQZSB-PAPER-162-12":{"id":"CQZSB-PAPER-162-12","method":"先还原f的输入范围，再约束新的输入。","steps":["当x∈[−2,3]时，x−1∈[−3,2]，所以f的输入范围为[−3,2]","要求−3≤2x−3≤2，解得0≤x≤5/2"],"conclusion":"按教材约定定义域为[0,5/2]，选B。","pitfall":"[−2,3]是f(x−1)中x的范围，不是f的输入范围。","caveat":""},"CQZSB-PAPER-162-13":{"id":"CQZSB-PAPER-162-13","method":"判断两个因子的奇偶性。","steps":["对数真数为正给出定义域(−1,1)","(e⁻ˣ−1)/(e⁻ˣ+1)=−(eˣ−1)/(eˣ+1)，第一因子为奇","ln((1+x)/(1−x))是第二因子的相反数，第二因子也为奇"],"conclusion":"两奇函数之积为偶函数，选B。","pitfall":"乘积的奇偶性要先确认公共定义域对称。","caveat":""},"CQZSB-PAPER-162-14":{"id":"CQZSB-PAPER-162-14","method":"分别列出两个反三角函数的输入条件。","steps":["arcsin x要求−1≤x≤1","arctan x对全部实数有定义","二者取交集"],"conclusion":"定义域[−1,1]。","pitfall":"arcsin与arctan的定义域不同，前者有限制。","caveat":""},"CQZSB-PAPER-162-15":{"id":"CQZSB-PAPER-162-15","method":"直接用奇函数的定义。","steps":["奇函数满足f(−x)=−f(x)","取x=2，得f(−2)=−f(2)=−3"],"conclusion":"f(−2)=−3。","pitfall":"奇函数在对称两点的函数值互为相反数。","caveat":""},"CQZSB-PAPER-162-16":{"id":"CQZSB-PAPER-162-16","method":"对数与分母根式同时成立。","steps":["ln(x+1)要求x+1>0，即x>−1","分母√(2−x)要求2−x>0，即x<2","取交集"],"conclusion":"定义域(−1,2)。","pitfall":"x=2虽然根式为0，但分母不能为0。","caveat":""},"CQZSB-PAPER-163-17":{"id":"CQZSB-PAPER-163-17","method":"先求定义域，再用倒数对数公式。","steps":["(1+x)/(1−x)>0等价于−1<x<1","f(−x)=lg((1−x)/(1+x))=−lg((1+x)/(1−x))"],"conclusion":"f是奇函数，定义域(−1,1)。","pitfall":"lg与ln底数不同，但奇偶性推导使用的倒数法则相同。","caveat":""},"CQZSB-PAPER-163-18":{"id":"CQZSB-PAPER-163-18","method":"由乘积关系把f(−x)替换为倒数。","steps":["f(x)>0，所以f(−x)=1/f(x)，且分母f(x)+1不为0","g(−x)=(1/f(x)−1)/(1/f(x)+1)=(1−f(x))/(1+f(x))","因此g(−x)=−g(x)"],"conclusion":"在题设对称定义域上，g为奇函数。","pitfall":"应把分子分母同时乘f(x)，不能只改分子。","caveat":""},"CQZSB-PAPER-164-19":{"id":"CQZSB-PAPER-164-19","method":"直接对F取负自变量。","steps":["F的自然定义域是f(x)、f(−x)都存在之处，因此对称","F(−x)=f(x)−f(−x)=−[f(−x)−f(x)]"],"conclusion":"F是奇函数。","pitfall":"无需知道f本身的奇偶性；若F恒为0，它也同时为偶函数。","caveat":""},"CQZSB-PAPER-164-20":{"id":"CQZSB-PAPER-164-20","method":"把指数分式通分并代入−x。","steps":["定义域为x≠0，关于原点对称","f(x)=x(eˣ+1)/(2(eˣ−1))","f(−x)=−x(e⁻ˣ+1)/(2(e⁻ˣ−1))=x(eˣ+1)/(2(eˣ−1))"],"conclusion":"f为偶函数，选B。","pitfall":"原式在0处无定义，不能因化简而擅自补入。","caveat":""},"CQZSB-PAPER-164-21":{"id":"CQZSB-PAPER-164-21","method":"利用两个对数真数互为倒数。","steps":["√(1+x²)>|x|，所以x+√(1+x²)>0，定义域ℝ","(√(1+x²)+x)(√(1+x²)−x)=1","故f(−x)=ln(1/(x+√(1+x²)))=−f(x)"],"conclusion":"f为奇函数。","pitfall":"先确认真数恒正，不能直接把ln中的和拆开。","caveat":""},"CQZSB-PAPER-164-22":{"id":"CQZSB-PAPER-164-22","method":"取负自变量，看分子分母变化。","steps":["在a>0时，aˣ+a⁻ˣ>0，定义域ℝ","f(−x)=(a⁻ˣ−aˣ)/(a⁻ˣ+aˣ)=−f(x)"],"conclusion":"通常指数底数条件下为奇函数，图像关于原点对称，选C。","pitfall":"分子变号而分母不变。","caveat":"题干未明示a>0；若a=1则函数恒0，还关于x轴、y轴对称，单选需通常底数a>0且a≠1。"},"CQZSB-PAPER-165-23":{"id":"CQZSB-PAPER-165-23","method":"解出eˣ，并用原值域作反函数定义域。","steps":["由y(eˣ+1)=eˣ得eˣ=y/(1−y)","因为eˣ>0，所以原值域为(0,1)","两边取ln，再交换变量"],"conclusion":"反函数y=ln(x/(1−x))，定义域(0,1)。","pitfall":"原函数值域不是全部正数，而是严格位于0与1之间。","caveat":""},"CQZSB-PAPER-166-24":{"id":"CQZSB-PAPER-166-24","method":"替换x为1/x，构造二元一次方程消元。","steps":["原式为2f(x)+f(1/x)=1/x，x≠0","替换得f(x)+2f(1/x)=x","原式乘2减去新式，得到3f(x)=2/x−x"],"conclusion":"f(x)=2/(3x)−x/3，x≠0。","pitfall":"替换时右端1/x也要随之变成x。","caveat":""},"CQZSB-PAPER-166-25":{"id":"CQZSB-PAPER-166-25","method":"移项后取以2为底的对数。","steps":["y−5=2^(3−x)>0，故原值域(5,+∞)","log₂(y−5)=3−x，解得x=3−log₂(y−5)","交换变量"],"conclusion":"反函数y=3−log₂(x−5)，定义域(5,+∞)。","pitfall":"减号来自指数中的−x，不能写成加log₂。","caveat":""},"CQZSB-PAPER-166-26":{"id":"CQZSB-PAPER-166-26","method":"用给定区间保证sin可逆。","steps":["3x∈[−π/4,π/4]，sin在该区间严格递增","原值域为[−√2,√2]","由sin(3x)=y/2得x=(1/3)arcsin(y/2)"],"conclusion":"反函数y=(1/3)arcsin(x/2)，定义域[−√2,√2]。","pitfall":"反函数定义域取实际值域，不能照搬[−2,2]。","caveat":""},"CQZSB-PAPER-166-27":{"id":"CQZSB-PAPER-166-27","method":"解一次分式方程。","steps":["y=x/(x+1)给出y(x+1)=x，即x=y/(1−y)","原函数不能取到1，所以反函数输入x≠1","代入2得2/(1−2)=−2"],"conclusion":"f⁻¹(x)=x/(1−x)，x≠1；f⁻¹(2)=−2。","pitfall":"f⁻¹表示反函数，不是1/f。","caveat":""},"CQZSB-PAPER-167-28":{"id":"CQZSB-PAPER-167-28","method":"把内层整体设为新变量。","steps":["令t=√x+1，则t≥1，√x=t−1","x+2√x=(t−1)²+2(t−1)=t²−1"],"conclusion":"f(x)=x²−1，题设能确定的范围为x≥1。","pitfall":"换元后必须保留t≥1，不能随意扩展。","caveat":"题设未规定f在x<1的值，不能唯一确定该部分。"},"CQZSB-PAPER-167-29":{"id":"CQZSB-PAPER-167-29","method":"把1/x作为完整输入代入。","steps":["x≠0时f(1/x)=(1/x)/(1+1/x²)=x/(x²+1)","f(1/2)=(1/2)/(1+1/4)=2/5"],"conclusion":"f(1/x)=x/(x²+1)（x≠0），f(1/2)=2/5。","pitfall":"化简后的公式在0有意义，但原复合式仍不允许x=0。","caveat":""},"CQZSB-PAPER-167-30":{"id":"CQZSB-PAPER-167-30","method":"令t=ln x，改写所有原变量。","steps":["原x>0，令t=ln x，则x=eᵗ且t可取ℝ","f(t)=ln(eᵗ/(1+e^(2t)))=t−ln(1+e^(2t))","取t=1代入"],"conclusion":"f(x)=x−ln(1+e²ˣ)，f(1)=1−ln(1+e²)。","pitfall":"ln x换元后，分母中的x²应变成e^(2t)。","caveat":""},"CQZSB-PAPER-167-31":{"id":"CQZSB-PAPER-167-31","method":"整体换元并保留不能取到的输入。","steps":["令t=1/x−1，则1/x=t+1且t≠−1","1/x²−1/x=(t+1)²−(t+1)=t²+t"],"conclusion":"题设确定f(x)=x²+x，x≠−1。","pitfall":"原变量x≠0导致新变量不能等于−1。","caveat":"原记录未注明x≠−1；仅凭题设不能确定f(−1)。"},"CQZSB-PAPER-167-32":{"id":"CQZSB-PAPER-167-32","method":"用三角恒等式把右端化为tan x的多项式。","steps":["sec²x=1+tan²x","令t=tan x，t可遍历全部实数","于是f(t)=1+t²+t"],"conclusion":"f(x)=1+x²+x，x∈ℝ。","pitfall":"sec²x等于1+tan²x，而不是1−tan²x。","caveat":""},"CQZSB-PAPER-168-34":{"id":"CQZSB-PAPER-168-34","method":"先找f输入范围再解新的双边不等式。","steps":["x∈[−1,1]时x−1∈[−2,0]","故要求−2≤2x+1≤0","减1再除以2，得−3/2≤x≤−1/2"],"conclusion":"按教材约定，定义域[−3/2,−1/2]。","pitfall":"先平移得到f的定义域，不能直接令2x+1落在[−1,1]。","caveat":""},"CQZSB-PAPER-168-35":{"id":"CQZSB-PAPER-168-35","method":"分别约束两个函数输入，并排除分母零点。","steps":["由x∈[−2,4]得f的输入范围[−5,1]","−5≤2x−1≤1给出−2≤x≤1","−5≤1−x≤1给出0≤x≤6","交集[0,1]再去掉x=0"],"conclusion":"定义域(0,1]。","pitfall":"函数输入限制求完后，还必须检查独立的分母x。","caveat":""},"CQZSB-PAPER-169-36":{"id":"CQZSB-PAPER-169-36","method":"对比定义域与实际函数值。","steps":["A的两个定义域分别为x≠0和x>0","B中√(x²)=|x|且两边定义域ℝ","C右式仅允许x≥0，D右式仅允许|x|≤1"],"conclusion":"相同函数为B。","pitfall":"变量上的根号或反三角函数会留下定义域限制。","caveat":""},"CQZSB-PAPER-169-37":{"id":"CQZSB-PAPER-169-37","method":"使内层输入落入f的定义域。","steps":["要求0<2x+1<1","减1得−1<2x<0，再除以2"],"conclusion":"定义域(−1/2,0)。","pitfall":"端点沿用严格不等号，不能加入。","caveat":""},"CQZSB-PAPER-169-38":{"id":"CQZSB-PAPER-169-38","method":"考察已知x范围内2ˣ的值域。","steps":["x∈(4,8)，2ˣ严格递增","因此内层2ˣ遍历(2⁴,2⁸)=(16,256)"],"conclusion":"按教材约定，f(x)定义域为(16,256)。","pitfall":"指数值域应计算2⁴与2⁸，不是把区间取对数。","caveat":"严格地说题设只确定f在正数部分的定义域；f在非正数上是否定义无法由f(2ˣ)判断。"},"CQZSB-PAPER-169-39":{"id":"CQZSB-PAPER-169-39","method":"约束指数输入在(0,1)内。","steps":["要求0<eˣ<1","eˣ始终为正，而eˣ<1当且仅当x<0"],"conclusion":"定义域(−∞,0)。","pitfall":"eˣ不能等于0，因此不必再加下界。","caveat":""},"CQZSB-PAPER-170-40":{"id":"CQZSB-PAPER-170-40","method":"合并各段自变量区间。","steps":["三段分别允许[−1,0]、(0,3)、(3,+∞)","前两段并成[−1,3)，且任何一段都不包含3"],"conclusion":"定义域[−1,3)∪(3,+∞)，选D。","pitfall":"分段端点3两侧都有函数值，并不代表3本身有定义。","caveat":""},"CQZSB-PAPER-170-41":{"id":"CQZSB-PAPER-170-41","method":"根式、分母、反正弦条件同时成立。","steps":["1−x²≥0且x≠0，得x∈[−1,0)∪(0,1]","−1≤2x−2≤1，得1/2≤x≤3/2","取交集为[1/2,1]"],"conclusion":"定义域[1/2,1]，选B。","pitfall":"根号在分子上允许为0，因此x=1可以保留。","caveat":""},"CQZSB-PAPER-170-42":{"id":"CQZSB-PAPER-170-42","method":"反余弦约束与分母限制取交集。","steps":["−1≤x/2≤1给出−2≤x≤2","三次根式对全体实数有定义","x(x+1)≠0，排除0、−1"],"conclusion":"定义域[−2,−1)∪(−1,0)∪(0,2]。","pitfall":"奇次根式不要求被开方数非负。","caveat":""},"CQZSB-PAPER-170-43":{"id":"CQZSB-PAPER-170-43","method":"逐项列出根号、对数和分母条件。","steps":["√x要求x≥0","ln(1−x)要求1−x>0，即x<1","作为分母还要求ln(1−x)≠0，即x≠0"],"conclusion":"定义域(0,1)。","pitfall":"ln的真数为正还不够，分母中的ln值也不能为0。","caveat":""},"CQZSB-PAPER-171-44":{"id":"CQZSB-PAPER-171-44","method":"因式分解后与对数限制求交。","steps":["分母根式要求x²−x−2=(x−2)(x+1)>0，即x<−1或x>2","ln(2x−7)要求x>7/2","两者交集为x>7/2"],"conclusion":"定义域(7/2,+∞)。","pitfall":"对数条件已比正半轴上的根式条件更严格。","caveat":""},"CQZSB-PAPER-176-真题1":{"id":"CQZSB-PAPER-176-真题1","method":"对抽象组合代入−x。","steps":["设H(x)=f(x)+f(−x)，则H(−x)=H(x)","A取负后变号，D中的f(x²)不变而x变号","C没有给定f性质，不能保证为偶"],"conclusion":"必为偶函数的是B。","pitfall":"选“必成立”时不能自行假设f是奇函数或偶函数。","caveat":""},"CQZSB-PAPER-176-真题2":{"id":"CQZSB-PAPER-176-真题2","method":"使2ˣ落在原定义域(0,1)。","steps":["2ˣ恒大于0","2ˣ<1=2⁰，由底数2>1可知x<0"],"conclusion":"定义域(−∞,0)。","pitfall":"指数函数永远不取0，但可无限接近0。","caveat":""},"CQZSB-PAPER-176-基础1":{"id":"CQZSB-PAPER-176-基础1","method":"使用同底对数乘积法则核验。","steps":["logₐb+logₐc=logₐ(bc)，在题设正数条件下恒成立","A左边用换底公式化为ln a/ln c=log꜀a，与右边一般互为倒数","C正确法则应是logₐ(bᶜ)=c logₐb"],"conclusion":"恒成立的是B。","pitfall":"对数把乘法变加法，不能把真数相加拆成对数之和。","caveat":""},"CQZSB-PAPER-176-基础2":{"id":"CQZSB-PAPER-176-基础2","method":"要求对数真数严格为正。","steps":["2x−1>0","移项并除以2，得x>1/2"],"conclusion":"定义域(1/2,+∞)，选B。","pitfall":"ln 0没有定义，因此1/2不能取。","caveat":""},"CQZSB-PAPER-176-基础3":{"id":"CQZSB-PAPER-176-基础3","method":"反正弦输入必须在[−1,1]。","steps":["−1≤(2x−1)/7≤1","乘7并加1，得−6≤2x≤8","除以2得−3≤x≤4"],"conclusion":"定义域[−3,4]，选C。","pitfall":"arcsin允许输入±1，所以两端闭合。","caveat":""},"CQZSB-PAPER-176-基础4":{"id":"CQZSB-PAPER-176-基础4","method":"排除分母为零的点。","steps":["分母x−6≠0，故x≠6","其余实数代入都有意义"],"conclusion":"定义域(−∞,6)∪(6,+∞)，选A。","pitfall":"分子为1不增加限制，排除的是6。","caveat":""},"CQZSB-PAPER-176-基础5":{"id":"CQZSB-PAPER-176-基础5","method":"根内非负，因式分解解二次不等式。","steps":["x²−x−6=(x−3)(x+2)","开口向上，两根之外乘积非负","所以x≤−2或x≥3"],"conclusion":"定义域(−∞,−2]∪[3,+∞)，选D。","pitfall":"根号不在分母中，两个零点都允许取到。","caveat":""},"CQZSB-PAPER-175-基础6":{"id":"CQZSB-PAPER-175-基础6","method":"分段定义域取各段条件的并集。","steps":["第一段允许−4≤x≤0，第二段允许0<x≤3","0已由第一段包含，两段连续拼接"],"conclusion":"定义域[−4,3]，选A。","pitfall":"常数段仍然受题中给定区间限制。","caveat":""},"CQZSB-PAPER-175-基础7":{"id":"CQZSB-PAPER-175-基础7","method":"比较指数和定义域。","steps":["A、D的指数为|x|，负x时与x不同","B的指数虽化为x，但只允许x≥0","C中(∛x)³=x对任意实数都成立"],"conclusion":"与eˣ相同的是C。","pitfall":"√(x²)=|x|，而(√x)²只在x≥0时成立。","caveat":""},"CQZSB-PAPER-175-基础8":{"id":"CQZSB-PAPER-175-基础8","method":"逐段求值域再取并集。","steps":["x>0时2x−1的值域为(−1,+∞)","x=0时补入0","x<0时sin x能取遍[−1,1]，故sin x−1的值域为[−2,0]","并集为[−2,+∞)"],"conclusion":"值域[−2,+∞)，选C。","pitfall":"负半轴仍包含无穷多个完整正弦周期，正弦的±1都能取到。","caveat":""},"CQZSB-PAPER-175-基础9":{"id":"CQZSB-PAPER-175-基础9","method":"取负自变量逐项比较。","steps":["D中(e⁻ˣ−1)/(e⁻ˣ+1)=−(eˣ−1)/(eˣ+1)，定义域ℝ","A为偶函数，C在x≠0上为偶函数","B的f(−x)=−xe⁻ˣ通常不等于−xeˣ"],"conclusion":"奇函数为D。","pitfall":"出现因子x不能直接判奇，乘上的eˣ并非偶函数。","caveat":""},"CQZSB-PAPER-175-基础10":{"id":"CQZSB-PAPER-175-基础10","method":"利用对数真数在取负后互为倒数。","steps":["(1−x)/(1+x)>0给出−1<x<1","f(−x)=ln((1+x)/(1−x))=−f(x)"],"conclusion":"f为奇函数，选A。","pitfall":"定义域必须先验证关于原点对称。","caveat":""},"CQZSB-PAPER-175-基础11":{"id":"CQZSB-PAPER-175-基础11","method":"先识别括号内的偶函数，再乘x。","steps":["H(x)=f(x)+f(−x)满足H(−x)=H(x)","令G(x)=xH(x)，则G(−x)=−xH(−x)=−G(x)","A、C、D在取负自变量时均保持不变"],"conclusion":"必为奇函数的是B。","pitfall":"f本身无需具有奇偶性，括号组合已经是偶函数。","caveat":""},"CQZSB-PAPER-175-基础12":{"id":"CQZSB-PAPER-175-基础12","method":"逐个因子检查奇偶性。","steps":["x和sin x都是奇函数，其乘积x sin x为偶函数","cos(−x)=cos x，所以e^(cos x)也是偶函数","三个因子相乘后取负自变量函数值不变"],"conclusion":"该函数为偶函数，选D。","pitfall":"乘积含有x一般不能据此断定奇函数。","caveat":""},"CQZSB-PAPER-175-基础13":{"id":"CQZSB-PAPER-175-基础13","method":"用各项周期及有界性排除。","steps":["A的周期π，C的周期π","D中sin x周期2π、cos(x/2)周期4π，和的周期4π","B在x=2nπ处取值4n²π²，绝对值无界，而连续周期函数必有界"],"conclusion":"不是周期函数的是B。","pitfall":"三角因子周期性不会自动传给带有x²振幅的乘积。","caveat":""},"CQZSB-PAPER-175-基础14":{"id":"CQZSB-PAPER-175-基础14","method":"用导数符号或正弦图像判断。","steps":["sin x的导数cos x在[0,π/2]上非负，且内部为正","(0,π)跨过最大值点，后半段下降","C、D所列区间正弦递减"],"conclusion":"单调递增区间为B。","pitfall":"(0,π)内函数先增后减，不能把整段当作递增。","caveat":""},"CQZSB-PAPER-175-基础15":{"id":"CQZSB-PAPER-175-基础15","method":"给函数值找统一上下界。","steps":["−1≤sin x≤1，所以0≤1+sin x≤2","eˣ随x→+∞无界，ln x随x→+∞无界，tan x靠近π/2时无界"],"conclusion":"有界函数是B。","pitfall":"有界要求整个定义域上的统一界，不是局部区间内有界。","caveat":""},"CQZSB-PAPER-175-基础16":{"id":"CQZSB-PAPER-175-基础16","method":"从内到外依次拆开运算。","steps":["先令t=x³，再令v=tan t","接着u=v²，最后y=eᵘ","逐层代回得到e^((tan(x³))²)"],"conclusion":"复合次序与A一致，选A。","pitfall":"tan²(x³)是先取tan再平方，不是tan(x⁶)。","caveat":""},"CQZSB-PAPER-175-基础17":{"id":"CQZSB-PAPER-175-基础17","method":"令t=1/x后把原x换成1/t。","steps":["原式要求x≠0且x≠1/2，故t≠0、2","f(t)=(3/t+1)/(2/t−1)，分子分母同乘t得(3+t)/(2−t)"],"conclusion":"题设确定f(x)=(3+x)/(2−x)，x≠0、2；对应B。","pitfall":"换元不是把原公式中的x直接改名，需换成倒数。","caveat":"原记录未标出x=0不能由题设确定；B表示的代数式仍正确。"},"CQZSB-PAPER-175-基础18":{"id":"CQZSB-PAPER-175-基础18","method":"把反函数求值转为原函数方程。","steps":["g(7)=t等价于f(t)=7","t³−1=7，所以t³=8，t=2"],"conclusion":"g(7)=2，选C。","pitfall":"反函数求值是在问哪个输入能使原函数输出7。","caveat":""},"CQZSB-PAPER-175-基础19":{"id":"CQZSB-PAPER-175-基础19","method":"反函数交换定义域与值域。","steps":["原函数输入范围[1,5]，输出范围[2,7]","反函数把[2,7]中的输出还原为原输入，因此其值域为[1,5]"],"conclusion":"反函数值域[1,5]，选A。","pitfall":"不要把反函数的定义域[2,7]当成值域。","caveat":""},"CQZSB-PAPER-175-基础20":{"id":"CQZSB-PAPER-175-基础20","method":"区分基本初等函数与经运算复合的函数。","steps":["ln x属于基本初等函数中的对数函数","A是幂函数与三角函数之和，D是三角函数与根式的复合","B由不同区间的不同公式分段给出"],"conclusion":"基本初等函数为C。","pitfall":"“初等函数”和“基本初等函数”不是同一层次的概念。","caveat":""},"CQZSB-PAPER-174-填空1":{"id":"CQZSB-PAPER-174-填空1","method":"根式条件与分母不为零取交集。","steps":["121−x²≥0给出−11≤x≤11","11−x≠0排除x=11","保留左端点−11"],"conclusion":"定义域[−11,11)。","pitfall":"根内为0允许，但分母同时为0的11必须去掉。","caveat":""},"CQZSB-PAPER-174-填空2":{"id":"CQZSB-PAPER-174-填空2","method":"使sin x落在(0,1]内。","steps":["要求0<sin x≤1","上界对所有实数自动成立，只需sin x>0","正弦在每个(2kπ,(2k+1)π)内为正"],"conclusion":"定义域为所有(2kπ,(2k+1)π)的并集，k∈ℤ。","pitfall":"sin x=1允许，所以各区间中点不能排除，端点sin x=0不能取。","caveat":""},"CQZSB-PAPER-174-填空3":{"id":"CQZSB-PAPER-174-填空3","method":"反正弦限制作用于ln x。","steps":["ln x先要求x>0","再要求−1≤ln x≤1","指数函数递增，得e⁻¹≤x≤e"],"conclusion":"定义域[e⁻¹,e]。","pitfall":"arcsin允许输入±1，因此两端都保留。","caveat":""},"CQZSB-PAPER-174-填空4":{"id":"CQZSB-PAPER-174-填空4","method":"对已知区间计算内层线性函数的值域。","steps":["x∈[1,2]，3x+5随x递增","下端为3×1+5=8，上端为3×2+5=11"],"conclusion":"按教材约定，f的定义域为[8,11]。","pitfall":"这里是已知复合函数求原函数，应求内层值域，而不是解3x+5∈[1,2]。","caveat":""},"CQZSB-PAPER-174-填空5":{"id":"CQZSB-PAPER-174-填空5","method":"内层ln x−1必须落在[0,1]。","steps":["要求0≤ln x−1≤1，即1≤ln x≤2","指数化得到e≤x≤e²，该范围已满足x>0"],"conclusion":"定义域[e,e²]。","pitfall":"先移项再取指数，不能把ln x−1误作ln(x−1)。","caveat":""},"CQZSB-PAPER-174-填空6":{"id":"CQZSB-PAPER-174-填空6","method":"正切周期除以自变量系数。","steps":["tan u的最小正周期为π","要求3(x+T)+2与3x+2相差π，故3T=π"],"conclusion":"最小正周期π/3。","pitfall":"常数平移2不改变周期，系数3才改变周期。","caveat":""},"CQZSB-PAPER-174-填空7":{"id":"CQZSB-PAPER-174-填空7","method":"由差商符号识别单调性，再比较自变量。","steps":["当x₁>x₂时，题设迫使f(x₁)−f(x₂)<0，所以f严格递减","π>3，故−π<−3","递减函数在较大的−3处取更小值"],"conclusion":"f(−3)<f(−π)。","pitfall":"负数大小会反向，−π比−3更小。","caveat":""},"CQZSB-PAPER-174-填空8":{"id":"CQZSB-PAPER-174-填空8","method":"把2x+1整体代入平方。","steps":["f(2x+1)=2(2x+1)²+1","展开(2x+1)²=4x²+4x+1，乘2再加1"],"conclusion":"f(2x+1)=8x²+8x+3。","pitfall":"平方展开中间项4x不能漏掉。","caveat":""},"CQZSB-PAPER-174-填空9":{"id":"CQZSB-PAPER-174-填空9","method":"从最内层开始逐次代入分段函数。","steps":["−3<0，所以f(−3)=0","输入0用中间支，f(0)=2","输入2>0，用平方支，f(2)=4"],"conclusion":"f(f(f(−3)))=4。","pitfall":"第二次输入恰好等于0，不能沿用负数分支。","caveat":""},"CQZSB-PAPER-174-填空10":{"id":"CQZSB-PAPER-174-填空10","method":"代入分式并检查两层分母。","steps":["内层要求x≠−1","1+f(x)=1+(1−x)/(1+x)=2/(1+x)，在允许范围内不为0","f(f(x))=[2x/(1+x)]/[2/(1+x)]=x"],"conclusion":"f(f(x))=x，定义域ℝ去掉−1。","pitfall":"结果等于x并不意味着原来的禁点−1可恢复。","caveat":""},"CQZSB-PAPER-174-填空11":{"id":"CQZSB-PAPER-174-填空11","method":"把x−1整体改成新变量。","steps":["令t=x−1，则x=t+1","f(t)=(t+1)²+2(t+1)−3=t²+4t"],"conclusion":"f(x)=x²+4x。","pitfall":"换元后右端每一个原x都必须替换为t+1。","caveat":""},"CQZSB-PAPER-174-填空12":{"id":"CQZSB-PAPER-174-填空12","method":"令函数括号中的输入等于1。","steps":["2x=1给出x=1/2","f(1)=log₅√(4×1/2+3)=log₅√5=1/2"],"conclusion":"f(1)=1/2。","pitfall":"不能直接把右端原变量x取1，那样求到的是f(2)。","caveat":""},"CQZSB-PAPER-174-填空13":{"id":"CQZSB-PAPER-174-填空13","method":"解出内层函数的立方。","steps":["f(g(x))=8[g(x)]³=1−eˣ","除以8后取实数立方根，g(x)=∛(1−eˣ)/2","立方根对负数同样有定义"],"conclusion":"g(x)=(1/2)∛(1−eˣ)，定义域ℝ。","pitfall":"这是立方根，不需要附加1−eˣ≥0。","caveat":""},"CQZSB-PAPER-174-填空14":{"id":"CQZSB-PAPER-174-填空14","method":"取自然对数并交换变量。","steps":["原函数输出y>0","ln y=2x−1，解得x=(ln y+1)/2","交换x、y"],"conclusion":"反函数y=(ln x+1)/2，定义域(0,+∞)。","pitfall":"指数函数的反函数输入必须严格为正。","caveat":""},"CQZSB-PAPER-174-填空15":{"id":"CQZSB-PAPER-174-填空15","method":"使用反函数交换输入与输出。","steps":["反函数图像经过(1,5)，说明f⁻¹(1)=5","两边施加f得到f(5)=1"],"conclusion":"原函数图像必过(5,1)。","pitfall":"关于y=x对称时是坐标交换，不是坐标变号。","caveat":""},"CQZSB-PAPER-174-填空16":{"id":"CQZSB-PAPER-174-填空16","method":"按内层到外层逐次代入。","steps":["把v=e²ˣ代入u=sin v，得到u=sin(e²ˣ)","再代入y=ln u，得到ln(sin(e²ˣ))","实数条件为sin(e²ˣ)>0"],"conclusion":"复合函数y=ln(sin(e²ˣ))。","pitfall":"ln的真数必须为正，不能默认整个实数轴都有定义。","caveat":""},"CQZSB-PAPER-174-计算1":{"id":"CQZSB-PAPER-174-计算1","method":"最外层平方根要求对数值非负。","steps":["要求ln(3x+4)≥0","这等价于3x+4≥1，已保证对数真数为正","解得x≥−1"],"conclusion":"定义域[−1,+∞)。","pitfall":"仅要求3x+4>0不够，根号还要求ln值非负。","caveat":""},"CQZSB-PAPER-174-计算2(1)":{"id":"CQZSB-PAPER-174-计算2(1)","method":"根式与分母条件取交集。","steps":["√(x+2)要求x≥−2","1−x²≠0要求x≠−1、1","从[−2,+∞)删去这两个点"],"conclusion":"定义域[−2,−1)∪(−1,1)∪(1,+∞)。","pitfall":"分母的两个零点±1都要排除，−2可取。","caveat":""},"CQZSB-PAPER-174-计算2(2)":{"id":"CQZSB-PAPER-174-计算2(2)","method":"反余弦输入范围与分母根式严格正取交。","steps":["−1≤2x+3≤1给出−2≤x≤−1","x²+x=x(x+1)>0给出x<−1或x>0","交集为[−2,−1)"],"conclusion":"定义域[−2,−1)。","pitfall":"x=−1使分母为0必须排除，即使分子也为0也不允许。","caveat":""},"CQZSB-PAPER-173-计算3":{"id":"CQZSB-PAPER-173-计算3","method":"计算已知区间上内层的值域。","steps":["复合函数中的x从0到1","2x−1是递增线性函数，分别在端点取−1与1"],"conclusion":"按教材约定，f的定义域为[−1,1]。","pitfall":"这是求输入2x−1的范围，不是把[0,1]再作为f的输入限制。","caveat":""},"CQZSB-PAPER-173-计算4":{"id":"CQZSB-PAPER-173-计算4","method":"约束根式内层进入(0,1]。","steps":["0<√x−2≤1，即2<√x≤3","各数非负，可平方得4<x≤9"],"conclusion":"定义域(4,9]。","pitfall":"平方前先整理，左端严格不等号应保留。","caveat":""},"CQZSB-PAPER-173-计算5":{"id":"CQZSB-PAPER-173-计算5","method":"直接解立方方程。","steps":["f(g(x))=[g(x)]³+1=1+x","两边减1得[g(x)]³=x","实数立方根对每个实数唯一存在"],"conclusion":"g(x)=∛x，定义域ℝ。","pitfall":"立方与平方不同，实数立方根没有正负两个分支。","caveat":""},"CQZSB-PAPER-173-计算6":{"id":"CQZSB-PAPER-173-计算6","method":"用恒等式把右端写成sin x的多项式。","steps":["cos²x=1−sin²x，所以f(sin x)=2−sin²x","令t=sin x，则t∈[−1,1]","于是f(t)=2−t²"],"conclusion":"题设确定f(x)=2−x²，−1≤x≤1。","pitfall":"换元必须保留sin x的取值范围。","caveat":"题设无法确定f在[−1,1]之外的值。"},"CQZSB-PAPER-173-计算7":{"id":"CQZSB-PAPER-173-计算7","method":"把分式看作奇函数，与x相乘。","steps":["定义域ℝ，因为2ˣ+1>0","H(−x)=(2⁻ˣ−1)/(2⁻ˣ+1)=(1−2ˣ)/(1+2ˣ)=−H(x)","f(−x)=(−x)(−H(x))=f(x)"],"conclusion":"函数为偶函数。","pitfall":"分式取负自变量后要把分子分母同时乘2ˣ。","caveat":""},"CQZSB-PAPER-173-计算8":{"id":"CQZSB-PAPER-173-计算8","method":"解对数方程求出原输入。","steps":["原函数要求x>1，其值域为ℝ","由y−1=ln(x−1)得x−1=e^(y−1)，即x=e^(y−1)+1","交换变量"],"conclusion":"反函数y=e^(x−1)+1，定义域ℝ。","pitfall":"外面的+1与指数内的−1分别来自两次移项。","caveat":""},"CQZSB-PAPER-173-提升1":{"id":"CQZSB-PAPER-173-提升1","method":"根式、对数真数、对数非零三条件求交。","steps":["9−x²≥0得−3≤x≤3","x+2>0得x>−2","lg(x+2)≠0得x+2≠1，即x≠−1"],"conclusion":"定义域(−2,−1)∪(−1,3]，选C。","pitfall":"3使分子为0可以保留，−1使分母为0必须排除。","caveat":""},"CQZSB-PAPER-173-提升2":{"id":"CQZSB-PAPER-173-提升2","method":"指数内分母与对数项同时有意义。","steps":["1/x²要求x≠0","ln x要求x>0，已排除0","1−ln x≠0要求ln x≠1，即x≠e"],"conclusion":"定义域(0,e)∪(e,+∞)，选A。","pitfall":"e^(1/x²)本身没有额外符号限制，但其指数不能含零分母。","caveat":""},"CQZSB-PAPER-173-提升3":{"id":"CQZSB-PAPER-173-提升3","method":"核对定义域和对应法则，变量名称不影响函数。","steps":["A右式约去x−3后为x+2，但排除3","B右式=√(sin²x)=|sin x|","C只把自变量符号x换成t，法则与定义域不变","D左式=√x而右式=1/√x"],"conclusion":"相同函数为C。","pitfall":"函数相同不要求自变量用同一个字母。","caveat":""},"CQZSB-PAPER-172-提升4":{"id":"CQZSB-PAPER-172-提升4","method":"利用内层偶函数在对称点输出相等。","steps":["h为偶函数，所以h(−x)=h(x)","于是f(h(−x))=f(h(x))，无需知道f性质","其他组合中任意f可能破坏对称性"],"conclusion":"必成立的是f(h(x))为偶函数，选C。","pitfall":"偶函数放在外层不能保证整体为偶，关键是内层h对称点输出相同。","caveat":""},"CQZSB-PAPER-172-提升5":{"id":"CQZSB-PAPER-172-提升5","method":"先确定内层只可能输出0或1。","steps":["无论x如何，f(x)∈{0,1}","因为|0|≤1且|1|≤1，所以f(0)=f(1)=1","因此f(f(x))=1，再取一次f仍为f(1)=1"],"conclusion":"f(f(f(x)))恒为1，选B。","pitfall":"边界|x|=1属于取1的分支，因此f(1)=1。","caveat":""},"CQZSB-PAPER-172-提升6":{"id":"CQZSB-PAPER-172-提升6","method":"先求反正弦允许的非负值，再开平方。","steps":["最外层根号要求arcsin(2x−1)≥0","结合反正弦范围，这对应0≤2x−1≤1，即1/2≤x≤1","反正弦值遍历[0,π/2]，平方根值遍历[0,√(π/2)]"],"conclusion":"值域[0,√(π/2)]，选A。","pitfall":"题目问值域，不能把求得的自变量区间[1/2,1]当答案。","caveat":""},"CQZSB-PAPER-172-提升7":{"id":"CQZSB-PAPER-172-提升7","method":"用辅助角公式合并同频三角函数。","steps":["2sin(x+π/3)=2sin x cos(π/3)+2cos x sin(π/3)","右端等于sin x+√3cos x","振幅2、平移π/3均不改变频率1"],"conclusion":"最小正周期2π，选A。","pitfall":"√3是振幅系数，不是x的系数。","caveat":""},"CQZSB-PAPER-172-提升8":{"id":"CQZSB-PAPER-172-提升8","method":"检查内层值域能否与外层定义域相交。","steps":["A中2+x²≥2可开平方，B中eᵘ对任意实数u定义","C可在|x|≤1时保证x²∈[0,1]","D中e+x²≥e>1，永远不在arcsin的输入区间[−1,1]内"],"conclusion":"不能组成有非空实数定义域的函数的是D。","pitfall":"能够复合不代表对全体实数都成立，C仍能在有限区间复合。","caveat":""},"CQZSB-PAPER-172-提升9":{"id":"CQZSB-PAPER-172-提升9","method":"同时限制对数底数及真数。","steps":["底数2x−1>0且2x−1≠1，得x>1/2且x≠1","真数√(3x−2)>0，得x>2/3","合并得到x>2/3且x≠1"],"conclusion":"定义域(2/3,1)∪(1,+∞)。","pitfall":"对数真数必须严格正，因此根式内部不是≥0而是>0。","caveat":""},"CQZSB-PAPER-172-提升10":{"id":"CQZSB-PAPER-172-提升10","method":"证明取负后对数真数互为倒数。","steps":["√(4x²+1)>|2x|，所以定义域ℝ","(√(4x²+1)+2x)(√(4x²+1)−2x)=1","因此f(−x)=−f(x)"],"conclusion":"f为奇函数，图像关于原点对称。","pitfall":"不能把ln中的加法拆成两个对数。","caveat":""},"CQZSB-PAPER-172-提升11":{"id":"CQZSB-PAPER-172-提升11","method":"先还原一般输入，再代入2x。","steps":["令t=x+1，则原x=t−1，f(t)=1/(t−1)，t≠1","把t换成2x，得f(2x)=1/(2x−1)"],"conclusion":"f(2x)=1/(2x−1)，x≠1/2。","pitfall":"原式f(x+1)=1/x不意味着f(x)=1/(x+1)。","caveat":""},"CQZSB-PAPER-172-提升12":{"id":"CQZSB-PAPER-172-提升12","method":"展开差式并比较常数项。","steps":["f(x+1)=4(x+1)²+b(x+1)+5","减去f(x)后为8x+4+b","与8x+3恒等，得4+b=3"],"conclusion":"b=−1。","pitfall":"常数5会相消，但平方展开产生的常数4不能漏掉。","caveat":""},"CQZSB-PAPER-172-提升13":{"id":"CQZSB-PAPER-172-提升13","method":"先借奇函数在0处为0求参数，再验证。","steps":["定义域关于原点对称且非空，必须有a>0，进而0有定义","f(0)=lg√(2a)=0，故√(2a)=1，a=1/2","此时两真数乘积为(x+√(x²+1))(−x+√(x²+1))=1，所以f(−x)=−f(x)"],"conclusion":"a=1/2。","pitfall":"只用f(0)=0是必要条件，代回验证才能确认充分性。","caveat":""},"CQZSB-PAPER-172-提升14":{"id":"CQZSB-PAPER-172-提升14","method":"按原输出范围分别解出原输入。","steps":["x≤0时y=x²+1≥1，解得x=−√(y−1)，负根由x≤0决定","x>0时y=1−x<1，解得x=1−y","两支输出范围不重叠且覆盖ℝ，所以整体可逆"],"conclusion":"反函数y=−√(x−1)（x≥1）；1−x（x<1）。","pitfall":"平方根前负号由原分支的x≤0决定，端点1属于根式支。","caveat":""},"CQZSB-PAPER-172-提升15":{"id":"CQZSB-PAPER-172-提升15","method":"分别按内层输出比较阈值。","steps":["eˣ<1、=1、>1分别对应x<0、=0、>0，所以f(g(x))分别为1、0、−1","g(f(x))是对分段值1、0、−1取指数","当|x|<1、=1、>1时分别得到e、1、e⁻¹"],"conclusion":"f(g(x))：1（x<0）、0（x=0）、−1（x>0）；g(f(x))：e（|x|<1）、1（|x|=1）、e⁻¹（|x|>1）。","pitfall":"f(g(x))与g(f(x))的分段标准不同，不能直接交换结果。","caveat":""},"CQZSB-PAPER-172-提升16":{"id":"CQZSB-PAPER-172-提升16","method":"分子分母同除x²，凑出x+1/x。","steps":["原x≠0，令t=x+1/x，则t≤−2或t≥2","(x+x³)/(1+x⁴)=(x+1/x)/(x²+1/x²)","x²+1/x²=t²−2，故f(t)=t/(t²−2)"],"conclusion":"f(x)=x/(x²−2)，题设确定范围为(−∞,−2]∪[2,+∞)。","pitfall":"分母是t²−2，来自(x+1/x)²=x²+2+1/x²。","caveat":"题设不确定−2<x<2上的函数值，不能直接扩成分式的全部自然定义域。"},"CQZSB-PAPER-172-提升17":{"id":"CQZSB-PAPER-172-提升17","method":"用倒数替换得到第二式，再消元。","steps":["x≠0时2f(x)+f(1/x)=1/x","把x换成1/x得f(x)+2f(1/x)=x","原式乘2减去第二式，得3f(x)=2/x−x"],"conclusion":"f(x)=(2/x−x)/3，x≠0。","pitfall":"第二式的右端是x，代换要作用于整条等式。","caveat":""}}};
